import{u as s}from"./data_collaboration-BwD9_jUr.js";function e(t){return s("C","Conception",t)}const i=e({id:"conception-C01",number:11,title:"L'Idée et le Problème Réel",subtitle:"Distinguer une idée d'une opportunité, et un problème perçu d'un problème réel",badge:"Fiche C01 — Vision Systémique",meta:["5 nœuds · universel"],readingTime:"20 min",description:"Avant d'écrire une ligne de code ou de dessiner une interface, il faut comprendre quel problème on résout vraiment — et pourquoi ce problème mérite d'être résolu. Cette fiche donne les outils pour ne pas confondre une idée avec une opportunité, ni un problème exprimé avec un problème réel.",accent:"diagnostic",nodes:{ideeOpportunite:{id:"ideeOpportunite",label:"Idée vs Opportunité",icon:"💡",kind:"diagnostic",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>La plupart des produits ratent avant même d'être construits — non pas à cause d'un mauvais code, mais parce qu'ils répondaient à une idée et non à une opportunité. <strong>Une idée, c'est quelque chose qu'on trouve intéressant. Une opportunité, c'est un problème réel que suffisamment de personnes veulent résoudre.</strong> La confusion entre les deux est la cause numéro un des projets construits dans le vide.</p>",system:`<p>Ce nœud est le point de départ de toute la fiche. Il conditionne <strong>Problème ressenti / exprimé / réel</strong> (on ne peut pas distinguer les niveaux du problème sans avoir d'abord distingué idée et opportunité) et <strong>Biais du fondateur</strong> (le biais est précisément ce qui empêche de faire cette distinction). Il précède aussi directement les utilisateurs <span class="ref-fiche">→ C02</span> : comprendre si c'est une opportunité, c'est comprendre pour qui.</p>`,choice:{kind:"free",html:"<p>Il n'y a pas d'alternative à cette distinction — c'est un filtre cognitif, pas un outil parmi d'autres. Ce qui varie, c'est <strong>la méthode pour faire le tri</strong> :</p><p><strong>Test de la douleur :</strong> quelqu'un paie-t-il déjà pour résoudre ce problème, même avec une solution imparfaite ? Si oui, c'est une opportunité. Si non, c'est peut-être juste une idée.</p><p><strong>Test de la fréquence :</strong> ce problème arrive-t-il souvent dans la vie de quelqu'un, ou une fois tous les cinq ans ? Un problème rare, même douloureux, est rarement une bonne opportunité produit.</p><p><strong>Test de l'initiative :</strong> les gens ont-ils déjà essayé de résoudre ce problème eux-mêmes, avec des rustines, des tableurs, des workarounds ? Si oui, c'est un signal fort que le problème est réel.</p>"},senior:`<p>Un product manager expérimenté ne demande pas "est-ce que c'est une bonne idée ?" — il demande "qui souffre de ce problème aujourd'hui, et comment le résout-il ?" Si personne ne souffre encore, ou si les gens s'en accommodent sans chercher de solution, il repart collecter des données avant de continuer.</p><p>Il sait aussi que <strong>l'enthousiasme d'une idée est inversement corrélé à la rigueur avec laquelle on la valide</strong>. Plus une idée paraît évidente, plus elle mérite d'être challengée — parce que l'évidence est souvent le signe d'un biais non interrogé.</p>`,errors:`<p><strong>Pattern 1 — La validation par le compliment :</strong> on montre l'idée à des amis ou collègues qui disent "super idée !" et on prend ça pour une validation. Les gens polis confirment les idées par défaut. Seuls les comportements réels (payer, s'inscrire, revenir) valident une opportunité.</p>
<p><strong>Pattern 2 — Le problème trop large :</strong> "les gens perdent du temps au travail" est un observation, pas un problème actionnable. Un problème doit être suffisamment précis pour qu'on puisse imaginer une solution spécifique. Sans précision, on construit une solution générique qui ne résout rien vraiment.</p>
<p><strong>Pattern 3 — La solution cherche son problème :</strong> on a une technologie ou une idée de feature, et on cherche ensuite un problème auquel la coller. Le résultat est toujours un produit qui impressionne en démo mais que personne n'utilise au quotidien.</p>`,invariants:"<p>Les outils pour évaluer les opportunités changent — lean canvas, jobs-to-be-done, problem interviews. <strong>Ce qui ne change pas : une opportunité n'existe que si le problème existe indépendamment de ta solution.</strong> Si le problème disparaît dès qu'on enlève ta solution de l'équation, c'est que tu as inventé le problème en même temps que la solution.</p><p><strong>Ce qui change :</strong> les méthodes de validation (entretiens, landing pages, prototypes). <strong>Ce qui ne change pas :</strong> la nécessité de distinguer ce que les gens disent de ce qu'ils font.</p>",practice:{exercices:[{titre:"Le test des trois questions",etapes:["Formule ton idée en une phrase : 'Je veux construire X pour Y afin de Z'.","Pose-toi la question : est-ce que Y souffre de ce problème aujourd'hui, sans ma solution ?","Trouve deux ou trois personnes dans le profil Y et demande-leur comment elles gèrent ce problème actuellement — sans mentionner ta solution.","Note leurs réponses : est-ce qu'elles ont déjà une façon de le gérer ? Est-ce qu'elles en parlent spontanément comme d'un vrai problème ?"],output:"Une réponse claire à : est-ce une opportunité (le problème existe déjà) ou une idée (le problème n'existe que dans mon cadre) ?",critere:"Tu peux décrire comment les personnes interrogées gèrent ce problème aujourd'hui, sans avoir mentionné ta solution. Si tu ne peux pas, tu n'as pas encore validé l'opportunité."}],piege:"Poser des questions fermées qui orientent la réponse : 'Est-ce que tu trouves que X est un problème ?' donne presque toujours 'oui'. Pose des questions ouvertes sur le passé : 'La dernière fois que tu as eu ce problème, qu'est-ce que tu as fait ?'"},verification:["Quelle est la différence entre une idée et une opportunité ? Donne un exemple de chacun.","Tu as une idée d'app de gestion de plantes pour les gens qui voyagent souvent. Comment distingues-tu si c'est une opportunité réelle ou juste une idée ?","Pourquoi l'enthousiasme des proches pour une idée n'est-il pas une validation d'opportunité ?"]}},problemNiveaux:{id:"problemNiveaux",label:"Problème ressenti / exprimé / réel",icon:"🔍",kind:"modele",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>Les utilisateurs ne savent pas toujours ce qu'ils veulent — mais ils savent ce qu'ils ressentent. <strong>Le problème qu'ils expriment est souvent une interprétation du problème qu'ils ressentent, et rarement le problème réel qui les sous-tend.</strong> Construire sur le problème exprimé sans creuser donne des features inutilisées ou des solutions qui résolvent le symptôme mais pas la cause.</p>",system:`<p>Ce nœud est le cadre analytique central de C01. Il s'appuie sur <strong>Idée vs Opportunité</strong> (pour savoir qu'il y a un problème) et alimente <strong>Les 5 pourquoi</strong> (pour creuser du ressenti vers le réel) et <strong>Douleur vs Préférence</strong> (pour évaluer la sévérité). Il fonde ensuite la compréhension utilisateur <span class="ref-fiche">→ C02</span> : comprendre le problème réel est indissociable de comprendre qui en souffre.</p>`,choice:{kind:"free",html:`<p>Ce modèle à trois niveaux (ressenti → exprimé → réel) n'a pas d'alternative directe. Ce qui varie, c'est la méthode pour passer d'un niveau à l'autre :</p>
<p><strong>Entretiens utilisateurs :</strong> la méthode la plus directe. On écoute ce qu'ils expriment, on observe ce qu'ils font, on infère le réel. Exige de savoir poser des questions sans orienter.</p>
<p><strong>Analyse comportementale :</strong> pour les produits existants — logs, heatmaps, enregistrements de sessions. Ce que les gens font révèle le problème réel mieux que ce qu'ils disent.</p>
<p><strong>Shadowing :</strong> observer les utilisateurs dans leur environnement naturel sans interférer. Révèle des problèmes que les gens n'expriment jamais parce qu'ils les considèrent comme normaux.</p>`},senior:`<p>Un product manager expérimenté écoute ce que l'utilisateur dit, mais note mentalement la différence entre "ce qu'il dit" et "ce qu'il fait". <strong>Quand un utilisateur dit 'je veux un bouton pour exporter en PDF', le problème exprimé est 'je veux exporter'. Le problème réel est probablement 'je dois partager cette information avec quelqu'un qui n'a pas accès à l'outil'.</strong> La solution peut être un bouton PDF, un lien de partage, ou une intégration email — ça dépend du problème réel.</p>`,errors:`<p><strong>Pattern 1 — La feature demandée :</strong> l'utilisateur demande une feature spécifique, on la construit exactement telle quelle, et personne ne l'utilise. On a résolu le problème exprimé sans comprendre le problème réel — la feature répondait à un besoin qui n'était pas le vrai besoin.</p>
<p><strong>Pattern 2 — La généralisation prématurée :</strong> un utilisateur exprime un problème, on suppose que tous les utilisateurs ont le même problème réel, on construit une solution universelle. Chaque segment peut avoir un problème réel différent derrière le même problème exprimé.</p>
<p><strong>Pattern 3 — Le symptôme traité comme cause :</strong> on résout le problème ressenti (la frustration, l'inconfort) sans identifier sa source. L'utilisateur se sent mieux temporairement, mais le problème réel revient sous une autre forme.</p>`,invariants:"<p>Les techniques d'investigation changent — entretiens, analytics, A/B tests. <strong>Ce qui ne change pas : entre ce que les gens ressentent, ce qu'ils disent, et ce qu'ils font, c'est ce qu'ils font qui révèle le problème réel.</strong></p><p><strong>Ce qui change :</strong> les outils pour observer et analyser les comportements. <strong>Ce qui ne change pas :</strong> l'écart structurel entre le problème exprimé et le problème réel — il existera toujours, parce que les gens rationalisent après coup ce qu'ils font intuitivement.</p>",practice:{exercices:[{titre:"Décortiquer un problème sur trois niveaux",etapes:["Choisis un problème exprimé que tu as entendu (ou imagine-en un vraisemblable pour un contexte que tu connais).","Formule le problème ressenti : quelle émotion ou friction déclenche l'expression de ce problème ?","Formule le problème réel : quel besoin profond ou objectif sous-jacent explique ce ressenti ?","Imagine deux solutions différentes : une qui répond au problème exprimé, une qui répond au problème réel. Laquelle est plus durable ?"],output:"Un tableau à trois colonnes : problème ressenti / problème exprimé / problème réel, avec une solution possible pour chaque niveau.",critere:"La solution au problème réel rend la solution au problème exprimé inutile ou secondaire. Si ce n'est pas le cas, tu n'as pas encore trouvé le problème réel."}],piege:"Rester au niveau du problème exprimé parce que c'est plus confortable — il est précis, formulé, actionnable. Le problème réel demande de creuser, d'interroger, de remettre en question ce qu'on croit savoir. C'est un effort supplémentaire qui évite de construire la mauvaise chose."},verification:["Explique la différence entre un problème ressenti, exprimé, et réel avec un exemple concret.","Un utilisateur te dit 'j'ai besoin d'une meilleure barre de recherche'. Comment identifies-tu le problème réel derrière cette demande ?","Pourquoi résoudre le problème exprimé sans comprendre le problème réel crée-t-il des features inutilisées ?"]}},biaisFondateur:{id:"biaisFondateur",label:"Biais du fondateur",icon:"🕶",kind:"diagnostic",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>Presque tous les fondateurs de produits ont vécu le problème qu'ils veulent résoudre — ou croient l'avoir vécu. Cette proximité est une force (on comprend le problème de l'intérieur) et une faiblesse systémique : <strong>on confond son expérience personnelle avec l'expérience universelle.</strong> Le résultat est un produit conçu pour une version idéalisée de soi-même, pas pour les utilisateurs réels.</p>",system:'<p>Le biais du fondateur contamine tous les autres nœuds de C01 et la compréhension des utilisateurs <span class="ref-fiche">→ C02</span>. Il déforme <strong>Idée vs Opportunité</strong> (on prend son propre enthousiasme pour une validation), <strong>Problème ressenti/exprimé/réel</strong> (on projette son propre problème réel sur tous les utilisateurs), et <strong>Hypothèses vs faits</strong> <span class="ref-fiche">→ C02</span> (on prend ses propres convictions pour des faits).</p>',choice:{kind:"free",html:`<p>Il n'y a pas d'alternative à la prise de conscience du biais — c'est une condition préalable, pas une technique. Ce qui varie, c'est la façon de le contrecarrer :</p>
<p><strong>Entretiens avec des inconnus :</strong> parler à des gens qui ne te connaissent pas et qui n'ont aucune raison de te faire plaisir. Les amis valident, les inconnus challengent.</p>
<p><strong>Persona adverse :</strong> se forcer à décrire un utilisateur qui ne ressemble pas du tout à soi-même et tester si le produit a encore du sens pour lui.</p>
<p><strong>Kill your darlings :</strong> identifier la feature ou hypothèse à laquelle on tient le plus, et la tester en premier — parce que c'est là que le biais est le plus fort.</p>`},senior:"<p>Un product manager expérimenté commence chaque projet en listant explicitement ses propres biais : ce qu'il croit être vrai sur le marché, les utilisateurs, et le problème. Il les traite comme des hypothèses à invalider, pas comme des données. <strong>Il sait que plus il est proche du problème, plus il doit s'efforcer de l'observer depuis l'extérieur.</strong></p><p>Il se méfie aussi du biais de confirmation dans l'analyse des retours utilisateurs : on entend ce qu'on veut entendre. Il prend des notes brutes, il enregistre, il relit.</p>",errors:`<p><strong>Pattern 1 — L'utilisateur imaginaire :</strong> on design pour un utilisateur qui nous ressemble parfaitement — mêmes compétences techniques, même contexte d'usage, même tolérance à la complexité. Le produit est excellent pour cet utilisateur imaginaire et inaccessible pour les vrais utilisateurs.</p>
<p><strong>Pattern 2 — La validation sélective :</strong> on collecte des retours utilisateurs mais on n'entend que ceux qui confirment ce qu'on pense déjà. Les signaux négatifs sont rationalisés ("ils n'ont pas compris", "ce n'est pas notre cible"). Le biais opère même dans la phase de recherche.</p>
<p><strong>Pattern 3 — L'expertise comme prison :</strong> on a tellement d'expertise dans un domaine qu'on ne comprend plus comment un débutant perçoit le problème. On conçoit une solution évidente pour un expert et incompréhensible pour un novice.</p>`,invariants:`<p>Les outils de recherche changent — user interviews, surveys, analytics. <strong>Ce qui ne change pas : le biais du fondateur est structurel. Il ne disparaît pas avec l'expérience — il se déplace.</strong> Un fondateur expérimenté développe de nouveaux biais sur ce qui "marche toujours" basés sur ses succès passés.</p><p><strong>Ce qui change :</strong> les techniques pour détecter et corriger le biais. <strong>Ce qui ne change pas :</strong> la nécessité de les appliquer activement à chaque nouveau projet, même (surtout) quand on se croit exempt de biais.</p>`,practice:{exercices:[{titre:"Cartographier ses propres biais",etapes:["Choisis un projet ou une idée sur laquelle tu travailles (ou envisages de travailler).","Liste 5 choses que tu crois être vraies sur les utilisateurs cibles ou le problème.","Pour chacune, classe-la : est-ce un fait (tu as des données) ou une hypothèse (tu le crois mais tu ne l'as pas vérifié) ?","Identifie les deux hypothèses les plus importantes pour le succès du projet — celles dont tout le reste dépend.","Formule un test minimal pour chacune : comment pourrais-tu la valider ou l'invalider en moins d'une semaine ?"],output:"Une liste de 5 croyances classées fait/hypothèse, avec les deux plus critiques identifiées et un test associé.",critere:"Tes deux hypothèses critiques sont formulées de façon à pouvoir être invalidées — si tu ne peux pas imaginer de résultat qui prouverait que tu as tort, la formulation n'est pas assez précise."}],piege:"Lister des hypothèses anodines pour éviter l'inconfort de confronter les vraies croyances. Les biais les plus dangereux sont ceux qu'on protège inconsciemment — ce sont eux qu'il faut lister en premier."},verification:["Pourquoi quelqu'un qui a vécu le problème qu'il veut résoudre est-il particulièrement sujet au biais du fondateur ?","Tu lances une app de gestion de finances personnelles parce que tu as galéré avec ça toi-même. Quels biais spécifiques dois-tu surveiller ?","Quel est le paradoxe du biais du fondateur : en quoi l'expertise dans un domaine est-elle à la fois un atout et un risque ?"]}},cinqPourquoi:{id:"cinqPourquoi",label:"Les 5 pourquoi",icon:"❓",kind:"modele",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>La plupart des analyses de problèmes s'arrêtent à la première explication plausible. <strong>Les 5 pourquoi forcent à descendre d'un niveau à chaque réponse, jusqu'à atteindre la cause racine plutôt que le symptôme.</strong> L'outil vient du manufacturing Toyota, mais s'applique identiquement à l'analyse de problèmes produit : le problème qu'un utilisateur exprime est rarement le problème qu'il faut résoudre.</p>",system:`<p>Les 5 pourquoi sont l'outil opérationnel du nœud <strong>Problème ressenti/exprimé/réel</strong>. Ils permettent de passer du problème exprimé au problème réel. Ils s'appliquent aussi dans <strong>Douleur vs Préférence</strong> (pour évaluer la profondeur d'un problème) et dans la priorisation <span class="ref-fiche">→ C05</span>, afin d'éviter de prioriser des symptômes plutôt que des causes.</p>`,choice:{kind:"free",html:`<p>Les 5 pourquoi ne sont pas le seul outil d'analyse causale — mais c'est le plus accessible et le plus rapide à appliquer. Les alternatives :</p>
<p><strong>Fishbone diagram (Ishikawa) :</strong> explore les causes en parallèle (méthodes, machines, personnes, matière...). Utile quand plusieurs causes racines coexistent. Plus long, mais plus exhaustif.</p>
<p><strong>Arbre des problèmes :</strong> représentation visuelle des relations cause-effet. Utile pour les problèmes complexes avec beaucoup d'interdépendances. Standard dans les projets de développement international.</p>
<p><strong>Règle :</strong> utilise les 5 pourquoi pour les analyses rapides et individuelles. Passe à une approche plus structurée quand le problème implique plusieurs équipes ou systèmes complexes.</p>`},senior:`<p>Un product manager expérimenté utilise les 5 pourquoi comme un réflexe de conversation, pas comme un exercice formel. Quand un utilisateur dit "je n'arrive pas à trouver mes fichiers", il ne note pas "améliorer la recherche" — il pose un pourquoi. Et un autre. Jusqu'à comprendre si le vrai problème est l'organisation, la nomenclature, les droits d'accès, ou quelque chose d'entièrement différent.</p><p><strong>Il sait aussi quand s'arrêter avant cinq :</strong> parfois trois pourquoi suffisent. L'objectif est la cause actionnable, pas le nombre de niveaux.</p>`,errors:`<p><strong>Pattern 1 — Le pourquoi rhétorique :</strong> on pose les pourquoi mais on oriente les réponses vers la conclusion qu'on veut atteindre. L'outil devient une façon de légitimer une décision déjà prise plutôt qu'une vraie investigation.</p>
<p><strong>Pattern 2 — La cause unique :</strong> on s'arrête à la première cause racine trouvée. Souvent, plusieurs causes racines coexistent et se renforcent. S'arrêter à une seule donne une solution partielle.</p>
<p><strong>Pattern 3 — La cause hors de portée :</strong> on remonte jusqu'à une cause racine sur laquelle on n'a aucune prise (culture d'entreprise, politique nationale, nature humaine). On a trouvé la "vraie" cause, mais elle est inexploitable. Il faut remonter d'un niveau et chercher la cause actionnable.</p>`,invariants:"<p>La technique des 5 pourquoi a 80 ans et n'a pas changé. <strong>Ce qui ne change pas : une solution durable résout la cause, pas le symptôme.</strong> Résoudre le symptôme crée une solution à court terme qui ne fait que déplacer ou retarder le vrai problème.</p><p><strong>Ce qui change :</strong> le domaine d'application (produit, ops, support, code). <strong>Ce qui ne change pas :</strong> le réflexe de ne jamais accepter la première explication comme la cause racine.</p>",practice:{exercices:[{titre:"Appliquer les 5 pourquoi à un problème concret",etapes:["Choisis un problème que tu as observé ou vécu : un outil difficile à utiliser, un processus qui bugue, un comportement utilisateur inattendu.","Formule le problème comme un fait observable : 'Les utilisateurs abandonnent à l'étape 3 du formulaire.'","Pose 'pourquoi ?' à cette observation et formule une hypothèse de réponse.","Pose 'pourquoi ?' à cette réponse. Répète jusqu'à 5 fois ou jusqu'à atteindre une cause actionnable.","Identifie à quel niveau se situe la cause actionnable — pas forcément la plus profonde, mais celle sur laquelle tu peux agir."],output:"Une chaîne de 3 à 5 pourquoi avec une cause actionnable identifiée à la fin.",critere:"La cause identifiée est actionnable (tu peux faire quelque chose pour la changer) et expliquerait la résolution du problème si elle était traitée. Si la résolution de la cause ne résoudrait pas le problème, tu n'as pas encore trouvé la bonne cause."}],piege:"Confondre 'comment' et 'pourquoi'. 'Comment ça s'est passé ?' explore la séquence d'événements. 'Pourquoi ça s'est passé ?' cherche la cause. Les deux questions sont utiles, mais seul le 'pourquoi' mène à la cause racine."},verification:["Explique dans tes mots pourquoi s'arrêter à la première explication d'un problème est risqué.","Un utilisateur dit 'votre app est lente'. Applique les 5 pourquoi à cette observation — quelles causes racines possibles pourrais-tu atteindre ?","Quand doit-on s'arrêter avant d'avoir posé 5 pourquoi ? Quel est le vrai critère d'arrêt ?"]}},douleurPreference:{id:"douleurPreference",label:"Douleur vs Préférence",icon:"⚡",kind:"diagnostic",osLabel:"Universel",niveau:"Fondation",sections:{why:`<p>Deux idées peuvent recevoir le même accueil poli en entretien : "oui, ce serait pratique". Pourtant l'une déclenchera un changement d'habitude, l'autre sera oubliée dès que la conversation se termine. <strong>Une douleur est quelque chose que l'utilisateur ne peut pas ignorer — il doit le gérer, même mal, même avec des rustines.</strong> Une préférence est quelque chose qu'il aimerait bien avoir, mais sans lequel il vit très bien.</p>`,system:`<p>Ce nœud est le filtre final de C01 — après avoir identifié l'opportunité, compris les niveaux du problème, et appliqué les 5 pourquoi, il faut évaluer l'intensité. Il alimente directement la viabilité <span class="ref-fiche">→ C04</span> : une douleur forte sur un marché suffisant devient une opportunité défendable. Il alimente aussi la priorisation <span class="ref-fiche">→ C05</span> : on priorise d'abord les douleurs, jamais les préférences.</p>`,choice:{kind:"free",html:`<p>Plusieurs cadres permettent d'évaluer l'intensité d'un problème :</p>
<p><strong>Le test du dollar :</strong> l'utilisateur paierait-il pour une solution, même imparfaite ? Si oui, c'est une douleur. Si "ça serait sympa mais non", c'est une préférence.</p>
<p><strong>Le test du workaround :</strong> l'utilisateur a-t-il déjà bricolé une solution ? Un tableur maison, un processus manuel, une extension Chrome qui fait mal le travail ? Les workarounds sont le signe le plus fort d'une douleur réelle.</p>
<p><strong>Le test de la fréquence × intensité :</strong> un problème léger mais quotidien peut valoir plus qu'un problème intense mais rare. La douleur totale est le produit des deux.</p>`},senior:`<p>Un product manager expérimenté pose une question simple en entretien : <strong>"Qu'est-ce que tu fais aujourd'hui pour gérer ce problème ?"</strong> Si la réponse est "rien, ça ne me dérange pas vraiment", c'est une préférence. Si la réponse est "j'ai un fichier Excel que j'update tous les lundis matin pendant une heure", c'est une douleur.</p><p>Il sait aussi que les douleurs sont plus faciles à monétiser — les gens paient pour faire disparaître une douleur bien plus facilement que pour obtenir un plaisir supplémentaire.</p>`,errors:`<p><strong>Pattern 1 — La feature de confort :</strong> on construit quelque chose qui rend l'expérience plus agréable, pas plus nécessaire. Les utilisateurs l'apprécient quand on leur en parle, mais ne le cherchent pas activement. Le taux d'activation reste bas malgré un bon retour qualitatif.</p>
<p><strong>Pattern 2 — L'intensité surévaluée :</strong> dans les entretiens, les gens expriment les problèmes avec une intensité supérieure à leur comportement réel. "Je déteste ça" ne signifie pas "je paierais pour que ça change". Seul le comportement (payer, changer d'outil, bricoler) révèle l'intensité réelle.</p>
<p><strong>Pattern 3 — La douleur du segment marginal :</strong> on identifie une douleur réelle, mais elle ne concerne qu'un très petit segment d'utilisateurs. Le problème est réel pour eux, mais le marché adressable est trop petit pour construire un produit viable.</p>`,invariants:"<p>Les outils pour évaluer l'intensité d'un problème changent. <strong>Ce qui ne change pas : les utilisateurs ne changeront pas leurs habitudes pour une préférence. Ils changeront pour une douleur.</strong> La résistance au changement est inversement proportionnelle à l'intensité de la douleur.</p><p><strong>Ce qui change :</strong> les méthodes pour mesurer l'intensité (willingness to pay, behavioral data, churn analysis). <strong>Ce qui ne change pas :</strong> la distinction fondamentale entre ce qu'on aimerait avoir et ce dont on ne peut pas se passer.</p>",practice:{exercices:[{titre:"Classer des problèmes sur l'axe douleur–préférence",etapes:["Liste 5 problèmes liés à un domaine que tu connais (travail, loisir, étude).","Pour chacun, pose-toi : est-ce que les gens ont déjà un workaround ? Lequel ?","Évalue la fréquence (combien de fois par semaine ce problème se pose) et l'intensité (sur une échelle de 1 à 5, quel impact sur la productivité ou le bien-être).","Classe les 5 problèmes de la douleur la plus forte à la préférence la plus légère."],output:"Un classement de 5 problèmes avec pour chacun : workaround existant, fréquence, intensité, et classification douleur/préférence.",critere:"Les problèmes classés comme 'douleur' ont tous un workaround existant. Si un problème classé 'douleur' n'a pas de workaround, soit tu as surestimé son intensité, soit les gens ont abandonné — ce qui est aussi une forme de workaround."}],piege:"Évaluer l'intensité par ce que les gens disent plutôt que par ce qu'ils font. 'J'en ai marre de ça' est une expression de frustration, pas une mesure d'intensité. Cherche les comportements : est-ce qu'ils ont investi du temps, de l'argent, ou de l'énergie pour contourner ce problème ?"},verification:["Quelle est la différence entre une douleur et une préférence ? Pourquoi cette distinction est-elle critique avant de construire un produit ?","Un utilisateur dit 'je trouverais ça pratique d'avoir une vue calendrier dans votre outil'. Est-ce une douleur ou une préférence ? Comment le détermines-tu ?","Pourquoi les douleurs sont-elles plus faciles à monétiser que les préférences ? Quel principe psychologique est en jeu ?"]}}},maps:{universel:{viewBox:"0 0 820 280",nodes:[{id:"ideeOpportunite",x:30,y:108,w:140,h:65},{id:"problemNiveaux",x:220,y:40,w:140,h:65},{id:"biaisFondateur",x:220,y:175,w:140,h:65},{id:"cinqPourquoi",x:420,y:108,w:130,h:65},{id:"douleurPreference",x:610,y:108,w:150,h:65}],edges:[{x1:170,y1:130,x2:218,y2:80,label:"creuse"},{x1:170,y1:148,x2:218,y2:195,label:"révèle"},{x1:360,y1:72,x2:418,y2:130,label:"nourrit"},{x1:360,y1:205,x2:418,y2:148,label:"filtre"},{x1:550,y1:140,x2:608,y2:140,label:"évalue"}]}}}),n=e({id:"conception-C02",number:12,title:"Les Utilisateurs",subtitle:"Comprendre pour qui on construit, ce qu'ils font vraiment, et comment le valider sans produit",badge:"Fiche C02 — Vision Systémique",meta:["5 nœuds · universel"],readingTime:"20 min",description:"Construire le bon produit pour les mauvaises personnes ou construire pour une image mentale d'utilisateur plutôt que pour des utilisateurs réels — c'est le deuxième piège après la confusion idée/opportunité. Cette fiche donne les outils pour comprendre qui sont vraiment les utilisateurs, ce qui les motive, et comment valider ces hypothèses avant de construire.",accent:"diagnostic",nodes:{utilisateurAcheteurDecideur:{id:"utilisateurAcheteurDecideur",label:"Utilisateur / Acheteur / Décideur",icon:"👥",kind:"modele",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>Dans beaucoup de produits, la personne qui utilise l'outil, la personne qui paie, et la personne qui décide de l'acheter sont trois personnes différentes. <strong>Optimiser pour l'utilisateur sans comprendre ce que veut l'acheteur ou ce qui convainc le décideur, c'est construire un produit que personne ne signe.</strong> Cette confusion est particulièrement fréquente en B2B — le manager décide, le budget vient des finances, et les équipes utilisent.</p>",system:`<p>Ce nœud est fondamental pour toute la fiche C02. Il conditionne <strong>Jobs-to-be-done</strong> (chaque rôle a un job différent), <strong>Contexte d'usage</strong> (l'utilisateur et l'acheteur vivent dans des contextes différents), et <strong>Hypothèses vs faits</strong> (les hypothèses sur les motivations varient selon le rôle). Il nourrit aussi la viabilité <span class="ref-fiche">→ C04</span> : le modèle économique dépend de qui paie, pas seulement de qui utilise.</p>`,choice:{kind:"free",html:`<p>La distinction utilisateur/acheteur/décideur s'applique différemment selon le contexte :</p>
<p><strong>B2C (consommateur direct) :</strong> souvent les trois rôles sont la même personne. La complexité vient des influenceurs (recommandations, avis) qui ne sont ni utilisateurs ni acheteurs mais influencent la décision.</p>
<p><strong>B2B (entreprise) :</strong> les trois rôles sont presque toujours séparés. Le décideur (DG, DSI) définit le budget, l'acheteur (responsable d'équipe) évalue les options, l'utilisateur (employé) travaille avec l'outil. Chacun a des critères de décision différents.</p>
<p><strong>B2B2C (via un intermédiaire) :</strong> une quatrième couche — la plateforme ou le partenaire qui distribue. Ses contraintes s'ajoutent aux trois rôles.</p>`},senior:"<p>Un product manager expérimenté identifie en premier lieu qui a le pouvoir de bloquer l'adoption — pas qui a envie du produit. Dans un contexte B2B, même si les utilisateurs adorent le produit, si le DSI a des contraintes de sécurité non adressées ou si le CFO trouve le pricing opaque, le deal ne se fait pas. <strong>Il conçoit des arguments différents pour chaque rôle, pas un pitch unique pour tous.</strong></p>",errors:`<p><strong>Pattern 1 — Le champion sans budget :</strong> on identifie un utilisateur enthousiaste qui "va faire remonter ça à sa direction". L'enthousiasme est réel, mais la personne n'a ni budget ni autorité. Six mois de travail commercial pour rien.</p>
<p><strong>Pattern 2 — Le décideur sans contexte :</strong> on parle au DG qui dit oui, mais personne n'a validé que les équipes utiliseront effectivement l'outil. Le contrat est signé, le déploiement échoue faute d'adoption.</p>
<p><strong>Pattern 3 — L'optimisation pour un seul rôle :</strong> on conçoit pour l'utilisateur (expérience fluide, features puissantes) sans penser à l'acheteur (ROI mesurable) ni au décideur (conformité, reporting). Le produit est excellent à l'usage mais invendable.</p>`,invariants:"<p>Les structures organisationnelles changent, les modèles d'achat évoluent. <strong>Ce qui ne change pas : dans tout achat, quelqu'un utilise, quelqu'un paie, et quelqu'un autorise — et leurs motivations sont rarement identiques.</strong></p><p><strong>Ce qui change :</strong> la structure exacte des rôles selon l'industrie et la taille d'entreprise. <strong>Ce qui ne change pas :</strong> la nécessité d'identifier et d'adresser chaque rôle séparément pour qu'un produit B2B soit adopté.</p>",practice:{exercices:[{titre:"Cartographier les rôles pour un produit",etapes:["Choisis un produit B2B que tu connais ou imagine (outil de gestion de projet, logiciel RH, plateforme de formation...).","Identifie un exemple concret d'organisation cible et liste : qui utilise l'outil au quotidien ? Qui décide de l'achat ? Qui signe le budget ?","Pour chaque rôle, formule leur critère de décision principal : qu'est-ce qui les convaincrait d'adopter ce produit ? Qu'est-ce qui les bloquerait ?","Identifie les points de friction entre les rôles : où leurs critères s'opposent-ils ?"],output:"Un tableau à trois colonnes (utilisateur / acheteur / décideur) avec pour chaque rôle : profil, critère d'adoption, et risque de blocage.",critere:"Les critères d'adoption des trois rôles sont distincts et parfois contradictoires. Si tous les critères se ressemblent, tu n'as pas encore fait la distinction réelle entre les rôles."}],piege:"Supposer que le rôle 'utilisateur' est le plus important parce que c'est lui qui interagit avec le produit. En B2B, le décideur qui ne touchera jamais l'outil peut bloquer un déploiement — son critère compte autant que celui de l'utilisateur."},verification:["Dans quel contexte la distinction utilisateur/acheteur/décideur est-elle la plus critique ? Pourquoi ?","Tu construis un outil de gestion de congés pour les PME. Qui sont l'utilisateur, l'acheteur, et le décideur ? Quels sont leurs critères respectifs ?","Pourquoi optimiser exclusivement pour l'expérience utilisateur peut-il mener à un échec commercial en B2B ?"]}},jobsToBeDone:{id:"jobsToBeDone",label:"Jobs-to-be-done",icon:"🔧",kind:"modele",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:`<p>Deux utilisateurs peuvent cliquer sur le même bouton pour des raisons complètement différentes. Si on ne comprend que le geste visible, on optimise l'interface ; si on comprend le progrès recherché, on peut repenser la solution entière. <strong>Le job-to-be-done est la tâche fonctionnelle, émotionnelle, ou sociale que l'utilisateur essaie d'accomplir.</strong> McDonald's a découvert que certains clients "engageaient" un milkshake pour tenir un long trajet ennuyeux — pas seulement pour boire quelque chose de sucré.</p>`,system:`<p>Le JTBD donne de la profondeur à <strong>Utilisateur/Acheteur/Décideur</strong> (chaque rôle a un job différent) et à <strong>Contexte d'usage</strong> (le job change selon le moment et la contrainte). Il alimente la solution <span class="ref-fiche">→ C03</span> : une bonne solution accomplit le job mieux que les alternatives actuelles. Il nourrit aussi la mesure <span class="ref-fiche">→ C06</span> : une métrique pertinente mesure si le job est réellement accompli.</p>`,choice:{kind:"free",html:`<p>Plusieurs cadres permettent de structurer la compréhension des motivations utilisateurs :</p>
<p><strong>Jobs-to-be-done (Christensen) :</strong> focus sur la tâche à accomplir et le progrès vers un résultat. Trois dimensions : fonctionnel (ce que ça fait), émotionnel (ce que ça fait ressentir), social (comment ça me positionne vis-à-vis des autres).</p>
<p><strong>Outcome-driven innovation (Ulwick) :</strong> décompose les jobs en "desired outcomes" mesurables. Plus structuré, utile pour des recherches quantitatives.</p>
<p><strong>User story mapping (Patton) :</strong> organise les activités des utilisateurs en séquences et niveaux d'abstraction. Plus proche du delivery que de la recherche.</p>
<p><strong>Règle :</strong> utilise JTBD pour la phase de découverte et de compréhension. Passe aux user stories pour la phase de delivery.</p>`},senior:`<p>Un product manager expérimenté formule les jobs à un niveau d'abstraction suffisant pour que la solution ne soit pas prédéterminée. <strong>"Je veux partager ce document" est trop concret (la solution est évidente). "Je veux que mon équipe soit alignée sur cette information" est le bon niveau</strong> — il ouvre des dizaines de solutions possibles (réunion, doc partagé, outil de collaboration, email, notification...). Le niveau d'abstraction du job détermine l'espace des solutions explorées.</p>`,errors:`<p><strong>Pattern 1 — Le job trop fonctionnel :</strong> on identifie uniquement la dimension fonctionnelle (ce que l'outil fait) et on rate les dimensions émotionnelles et sociales. Un outil de gestion de projet ne fait pas que gérer des tâches — il donne à son utilisateur une impression de contrôle et de sérieux vis-à-vis de son équipe.</p>
<p><strong>Pattern 2 — Le job confondu avec la feature :</strong> "je veux un export PDF" est une solution, pas un job. Le job est "je veux partager ce document avec quelqu'un qui n'a pas accès à l'outil". Confondre les deux ferme l'exploration des solutions alternatives.</p>
<p><strong>Pattern 3 — Le job unique pour tous :</strong> on identifie un job pour "les utilisateurs" sans distinguer les segments. Différents segments ont des jobs différents même avec le même produit — un débutant et un expert n'utilisent pas le même outil pour faire la même chose.</p>`,invariants:"<p>Le framework JTBD date des années 90 et ses fondements restent stables. <strong>Ce qui ne change pas : les utilisateurs engagent des produits pour accomplir du progrès dans leur vie. Le progrès peut être fonctionnel, émotionnel, ou social — et les trois dimensions comptent.</strong></p><p><strong>Ce qui change :</strong> les outils disponibles pour accomplir un job (disruption technologique). <strong>Ce qui ne change pas :</strong> le job lui-même — les gens voulaient rester en contact avec leurs proches avant les réseaux sociaux, et ils le voudront après.</p>",practice:{exercices:[{titre:"Formuler des jobs à la bonne altitude",etapes:["Choisis un produit du quotidien (Spotify, WhatsApp, Notion, Google Maps...).","Formule son job principal sous trois formes : trop concret (description de la feature), trop abstrait (générique et inapplicable), et au bon niveau (assez large pour laisser de l'espace aux solutions, assez précis pour guider).","Pour le job au bon niveau, identifie les trois dimensions : fonctionnelle, émotionnelle, sociale.","Identifie deux autres produits ou comportements qui accomplissent le même job — les 'compétiteurs indirects'."],output:"Un job formulé aux trois niveaux d'abstraction, avec ses trois dimensions et deux compétiteurs indirects identifiés.",critere:"Le job au bon niveau permet d'imaginer au moins trois solutions différentes. Si une seule solution vient immédiatement à l'esprit, le job est trop concret."}],piege:"Identifier les jobs en demandant aux utilisateurs 'quels sont vos besoins ?' — ils répondront avec des features, pas des jobs. Demande plutôt : 'La dernière fois que tu as utilisé ce produit, qu'est-ce que tu essayais d'accomplir ?' Le passé révèle les vrais jobs mieux que le présent."},verification:["Qu'est-ce qu'un job-to-be-done ? En quoi est-ce différent d'un besoin fonctionnel ou d'une feature ?","Formule le job-to-be-done d'un utilisateur qui ouvre Instagram à 7h du matin. Identifie les dimensions fonctionnelle, émotionnelle, et sociale.","Pourquoi identifier les compétiteurs indirects d'un produit (via le job) est-il plus utile que d'identifier ses compétiteurs directs ?"]}},contexteUsage:{id:"contexteUsage",label:"Contexte d'usage",icon:"🗺",kind:"diagnostic",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>Un produit ne s'utilise pas dans un vide. Il s'utilise dans un moment précis, avec des contraintes physiques et mentales, souvent en parallèle d'autres tâches. <strong>Ignorer le contexte d'usage, c'est concevoir pour un utilisateur idéal dans des conditions idéales — et rater l'utilisateur réel dans ses conditions réelles.</strong> Une app conçue en bureau sur écran large peut être inutilisable sur mobile dans le métro avec une main occupée.</p>",system:`<p>Le contexte d'usage donne de la chair aux <strong>Jobs-to-be-done</strong> (le même job peut avoir des contextes d'usage très différents) et aux <strong>Hypothèses vs faits</strong> (les hypothèses sur le contexte sont parmi les plus difficiles à valider sans observation). Il alimente la solution <span class="ref-fiche">→ C03</span> : les contraintes de contexte définissent ce qui est faisable, acceptable et prioritaire.</p>`,choice:{kind:"free",html:`<p>Plusieurs méthodes permettent de comprendre le contexte d'usage :</p>
<p><strong>Observation contextuelle (shadowing) :</strong> observer les utilisateurs dans leur environnement naturel, sans interférer. Révèle des contraintes et comportements invisibles en entretien.</p>
<p><strong>Diary study :</strong> demander aux utilisateurs de noter leurs expériences en temps réel sur plusieurs jours. Capture le contexte tel qu'il se passe, pas reconstruit de mémoire.</p>
<p><strong>Entretiens contextuels :</strong> conduire l'entretien là où l'utilisateur travaille normalement, avec son environnement réel visible. Plus riche qu'un entretien en salle de conférence.</p>
<p><strong>Règle :</strong> si tu ne peux pas observer, demande aux utilisateurs de te décrire la dernière fois qu'ils ont eu ce problème — lieu, heure, ce qu'ils faisaient en parallèle, leur état d'esprit.</p>`},senior:"<p>Un product manager expérimenté pense en scénarios d'usage avant de penser en features. <strong>Il se demande : dans quel moment précis de la journée/semaine/mois ce produit sera-t-il utilisé ? Avec quelles contraintes ? En remplacement de quoi ?</strong> Ces questions changent radicalement les décisions de design — une interface conçue pour une utilisation quotidienne rapide est différente d'une interface conçue pour une utilisation mensuelle approfondie.</p>",errors:`<p><strong>Pattern 1 — Le contexte de bureau :</strong> on conçoit en assumant que l'utilisateur est assis devant un grand écran, avec du temps, dans le calme. En réalité, les logiciels d'entreprise sont de plus en plus utilisés en mobilité, en réunion, ou simultanément avec d'autres outils.</p>
<p><strong>Pattern 2 — Le contexte unique :</strong> on identifie un contexte d'usage principal et on conçoit pour lui. Souvent, le même produit est utilisé dans des contextes radicalement différents selon le moment ou le profil utilisateur — chacun avec des contraintes distinctes.</p>
<p><strong>Pattern 3 — Le contexte oublié du déploiement :</strong> on pense au contexte d'usage de l'utilisateur final mais on oublie le contexte d'installation et de déploiement — qui fait l'onboarding ? Dans quelle situation d'urgence ou de tranquillité ? Le contexte d'onboarding détermine souvent le taux d'adoption.</p>`,invariants:"<p>Les outils et interfaces changent, les contextes d'usage évoluent. <strong>Ce qui ne change pas : un produit utilisé dans un contexte différent de celui pour lequel il a été conçu sera toujours sous-optimal.</strong> La contrainte du contexte réel prime toujours sur la logique du produit idéal.</p><p><strong>Ce qui change :</strong> les contextes eux-mêmes (travail hybride, mobile-first, vocal...). <strong>Ce qui ne change pas :</strong> la nécessité de comprendre où, quand, et dans quel état d'esprit le produit sera utilisé avant de le concevoir.</p>",practice:{exercices:[{titre:"Décrire trois scénarios d'usage concrets",etapes:["Choisis un produit ou une feature sur lequel tu travailles (ou imagine-en un).","Décris trois scénarios d'usage différents : lieu, moment, état d'esprit de l'utilisateur, ce qu'il faisait juste avant, contraintes physiques (une main libre ? bruit ? urgence ?).","Pour chaque scénario, identifie les contraintes qui impactent le design : taille d'écran, temps disponible, niveau de concentration, connexion internet...","Identifie le scénario le plus contraignant — conçois pour lui. Un design qui fonctionne dans le pire contexte fonctionne dans tous les contextes."],output:"Trois scénarios d'usage détaillés avec contraintes, et le scénario le plus contraignant identifié comme référence de conception.",critere:"Les trois scénarios sont suffisamment différents pour impliquer des décisions de design distinctes. Si les trois scénarios mènent au même design, ils ne sont pas assez contrastés."}],piege:"Décrire des contextes d'usage idéaux ('l'utilisateur ouvre l'app depuis son bureau') plutôt que des contextes réels ('l'utilisateur ouvre l'app dans le métro entre deux stations'). Les contextes idéaux ne révèlent pas les vrais défis de design."},verification:["Pourquoi comprendre le contexte d'usage est-il aussi important que comprendre le besoin fonctionnel ?","Tu conçois une app de suivi de chantier pour les conducteurs de travaux. Décris trois contextes d'usage possibles et leurs contraintes.","Quel est le principe derrière 'concevoir pour le scénario le plus contraignant' ? Dans quel cas ce principe ne s'applique-t-il pas ?"]}},hypothesesFaits:{id:"hypothesesFaits",label:"Hypothèses vs faits",icon:"⚖",kind:"validation",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>Toute connaissance sur les utilisateurs commence comme une hypothèse. Le problème n'est pas d'avoir des hypothèses — c'est de les confondre avec des faits. <strong>Une hypothèse non identifiée comme telle devient une certitude implicite qui guide les décisions sans jamais être remise en question.</strong> Les produits ratés sont souvent des produits construits sur des hypothèses traitées comme des faits, jamais testées, jusqu'au moment où le marché les invalide.</p>",system:`<p>Ce nœud est le filtre épistémique de toute la fiche C02. Il s'applique à <strong>Utilisateur/Acheteur/Décideur</strong> (nos modèles des rôles sont des hypothèses), <strong>Jobs-to-be-done</strong> (les jobs qu'on identifie sont des hypothèses), et <strong>Contexte d'usage</strong> (nos scénarios sont des hypothèses). Il prépare <strong>Valider sans produit</strong> et annonce la solution comme hypothèse <span class="ref-fiche">→ C03</span> : une hypothèse identifiée doit être testée avant d'être transformée en périmètre.</p>`,choice:{kind:"free",html:`<p>Plusieurs approches existent pour structurer le suivi des hypothèses :</p>
<p><strong>Hypothesis backlog :</strong> liste explicite de toutes les hypothèses du projet, classées par criticité et par niveau de confiance actuel. Chaque hypothèse a un test associé.</p>
<p><strong>Assumption mapping :</strong> grille 2x2 (criticité × niveau de confiance). Les hypothèses critiques et peu confirmées sont les priorités de recherche.</p>
<p><strong>Lean canvas :</strong> outil de structuration des hypothèses d'un business model complet. Utile pour capturer toutes les dimensions, moins utile pour le suivi quotidien.</p>
<p><strong>Règle :</strong> l'outil importe moins que la discipline — distinguer explicitement ce qu'on sait de ce qu'on croit, et avoir un processus pour réduire l'incertitude sur les hypothèses critiques.</p>`},senior:`<p>Un product manager expérimenté commence chaque projet en faisant la liste de ce qu'il ne sait pas encore — pas de ce qu'il sait. <strong>Il formule ses hypothèses de façon à ce qu'elles puissent être invalidées : "Si cette hypothèse est fausse, qu'est-ce que ça changerait ?"</strong> Une hypothèse qui ne peut pas être invalidée n'est pas une hypothèse — c'est une croyance.</p><p>Il maintient aussi cette discipline dans la durée : les faits d'aujourd'hui peuvent devenir des hypothèses fausses demain si le contexte change.</p>`,errors:`<p><strong>Pattern 1 — L'hypothèse déguisée en persona :</strong> on crée un persona détaillé ("Marie, 34 ans, responsable marketing...") et on le traite comme un fait. Le persona est une hypothèse sur qui sont les utilisateurs et ce qu'ils veulent — utile pour aligner les équipes, dangereux si on oublie que c'est une construction.</p>
<p><strong>Pattern 2 — La validation par le consensus interne :</strong> l'équipe se réunit, débat, et arrive à un consensus sur les hypothèses. Le consensus interne ne valide pas une hypothèse — seule la confrontation avec la réalité le fait. Un groupe peut être collectivement dans l'erreur.</p>
<p><strong>Pattern 3 — L'hypothèse non formulée :</strong> certaines hypothèses sont si évidentes qu'on ne les formule jamais — et donc on ne les teste jamais. "Les gens veulent gagner du temps" est une hypothèse. "Notre cible a accès à internet" est une hypothèse. Les hypothèses les plus évidentes sont souvent les plus dangereuses quand elles sont fausses.</p>`,invariants:"<p>Les méthodes de recherche changent. <strong>Ce qui ne change pas : toute décision basée sur une hypothèse non testée est un pari. Plus la décision est irréversible ou coûteuse, plus le pari est risqué.</strong></p><p><strong>Ce qui change :</strong> la vitesse à laquelle on peut tester des hypothèses (prototypes rapides, A/B tests, landing pages). <strong>Ce qui ne change pas :</strong> la nécessité de savoir ce qu'on sait versus ce qu'on croit — indépendamment des outils disponibles pour le tester.</p>",practice:{exercices:[{titre:"Trier les certitudes des hypothèses",etapes:["Prends un projet ou une idée de produit (réel ou imaginé).","Liste 10 affirmations que tu ferais sur les utilisateurs ou le marché ('Les utilisateurs veulent X', 'Le segment cible fait Y', 'La douleur principale est Z'...).","Pour chaque affirmation, classifie : Fait (tu as des données qui le prouvent), Hypothèse forte (tu as des indices, mais pas de preuve directe), Hypothèse faible (c'est une supposition sans données).","Pour les hypothèses faibles critiques, formule un test minimal : qu'est-ce que tu observerais si c'était vrai ? Comment peux-tu créer cette situation ?"],output:"Une liste de 10 affirmations classées fait/hypothèse forte/hypothèse faible, avec les hypothèses faibles critiques et leurs tests associés.",critere:"Au moins 4 de tes 10 affirmations sont des hypothèses (sinon tu n'as pas été assez honnête ou tu travailles sur un marché extrêmement bien connu). Les tests que tu formules peuvent être conduits en moins d'une semaine."}],piege:"Classer comme 'fait' des choses qu'on a entendues plusieurs fois ou qui font consensus dans l'équipe. La répétition ne transforme pas une hypothèse en fait. Seule la confrontation avec des données externes le fait."},verification:["Quelle est la différence entre un fait et une hypothèse dans le contexte de la compréhension utilisateur ?","Ton équipe est convaincue que 'les utilisateurs veulent une interface simple'. Comment détermines-tu si c'est un fait ou une hypothèse ?","Pourquoi une hypothèse qui ne peut pas être invalidée est-elle inutile pour guider les décisions produit ?"]}},validerSansProduit:{id:"validerSansProduit",label:"Valider sans produit",icon:"✅",kind:"validation",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:"<p>Une équipe peut passer trois mois à construire une première version, la lancer, puis découvrir en deux jours que l'hypothèse centrale était fausse. Ce n'est pas un problème d'exécution : c'est un apprentissage payé trop cher. <strong>Avant d'écrire une ligne de code, on peut valider les hypothèses les plus critiques avec des méthodes qui prennent des heures, pas des mois.</strong></p>",system:`<p>Ce nœud est la conclusion opérationnelle de C02. Il transforme les <strong>Hypothèses vs faits</strong> en actions de validation, et s'appuie sur les <strong>Jobs-to-be-done</strong> et le <strong>Contexte d'usage</strong> pour définir quoi tester. Il prépare la solution <span class="ref-fiche">→ C03</span> : on ne peut pas délimiter une bonne solution sans avoir validé les hypothèses critiques sur le problème et les utilisateurs.</p>`,choice:{kind:"free",html:`<p>Les méthodes de validation sans produit, du plus léger au plus élaboré :</p>
<p><strong>Entretiens de découverte :</strong> conversations ouvertes avec des utilisateurs potentiels pour comprendre leurs comportements et problèmes. Zéro coût, rapide, mais qualitatif — ne donne pas de mesures.</p>
<p><strong>Landing page + pré-inscription :</strong> décrire la solution et mesurer l'intent (email, pré-commande, demande d'accès). Donne une mesure quantitative de l'intérêt avant de construire.</p>
<p><strong>Prototype papier ou Figma :</strong> tester la compréhension et l'usage d'une interface sans coder. Révèle les problèmes d'UX et de concept avant l'implémentation.</p>
<p><strong>Wizard of Oz :</strong> simuler le produit manuellement (un humain fait ce que l'IA ou le système ferait). Valide le concept et la valeur perçue sans infrastructure.</p>
<p><strong>Fake door :</strong> proposer une feature dans le produit existant et mesurer le clic — si personne ne clique, inutile de la construire.</p>`},senior:`<p>Un product manager expérimenté choisit la méthode de validation la plus légère qui peut invalider l'hypothèse critique. <strong>La question n'est pas "comment prouver que j'ai raison ?" mais "quel est le test minimal qui pourrait me prouver que j'ai tort ?"</strong> Si le test ne peut pas invalider l'hypothèse, il ne sert à rien.</p><p>Il sait aussi que chaque méthode a ses limites : les entretiens sur-estiment souvent l'intérêt (les gens sont polis), les tests A/B ne fonctionnent que sur des produits existants avec du trafic, les landing pages mesurent l'intent mais pas l'usage réel.</p>`,errors:`<p><strong>Pattern 1 — La validation par démo :</strong> on montre le produit à des prospects et ils disent "c'est super". Ce n'est pas une validation — c'est de la politesse. La validation, c'est quelqu'un qui sort sa carte bleue, signe un engagement, ou change son comportement.</p>
<p><strong>Pattern 2 — Le prototype trop abouti :</strong> on construit un prototype si détaillé que les utilisateurs testent l'exécution (est-ce que l'interface est belle ?) plutôt que le concept (est-ce que ce produit résout mon problème ?). Un prototype en papier brouillon force à tester le concept.</p>
<p><strong>Pattern 3 — La validation d'une seule hypothèse :</strong> on valide l'hypothèse la plus facile (les gens ont le problème) et on oublie les autres hypothèses critiques (ils paieraient pour le résoudre, ils changeraient leur workflow, ils ont le budget...). Un produit peut rater même si le problème est validé.</p>`,invariants:"<p>Les outils de validation changent — prototypes no-code, tests utilisateurs en ligne, analytics. <strong>Ce qui ne change pas : une hypothèse validée avec un faux signal est pire qu'une hypothèse non testée — elle crée une fausse certitude qui oriente tout le produit dans la mauvaise direction.</strong></p><p><strong>Ce qui change :</strong> la facilité et la vitesse de mise en place des tests. <strong>Ce qui ne change pas :</strong> la nécessité que le signal mesuré représente réellement le comportement qu'on veut prédire.</p>",practice:{exercices:[{titre:"Concevoir un test de validation minimal",etapes:["Reprends les hypothèses critiques identifiées dans l'exercice précédent (ou formules-en deux nouvelles pour un projet imaginé).","Pour chaque hypothèse critique, choisis la méthode de validation la plus légère qui pourrait l'invalider.","Formule le test précisément : qui tu vas contacter, quoi tu vas leur montrer ou demander, quel signal tu vas mesurer, et quel résultat t'indiquerait que l'hypothèse est fausse.","Estime le temps nécessaire pour conduire ce test. Si c'est plus d'une semaine, simplifie."],output:"Pour chaque hypothèse critique : méthode choisie, description du test, signal mesuré, seuil d'invalidation, durée estimée.",critere:"Le test peut être conduit en moins d'une semaine, et tu as défini à l'avance ce qui constituerait une invalidation. Si tu n'as pas défini le seuil d'invalidation avant de conduire le test, les biais cognitifs interpréteront les résultats en ta faveur."}],piege:"Concevoir des tests qui ne peuvent que confirmer l'hypothèse. Si tu demandes 'est-ce que tu trouves que ce problème existe ?', la réponse sera presque toujours oui. Conçois des tests qui te donnent une chance réelle de découvrir que tu as tort."},verification:["Pourquoi construire le produit complet est-il la méthode de validation la plus chère et la plus risquée ?","Tu veux valider l'hypothèse 'les parents de jeunes enfants seraient prêts à payer pour une app de suivi des vaccins'. Propose deux méthodes de validation sans produit, du plus léger au plus élaboré.","Comment sais-tu qu'une validation a donné un vrai signal et pas un faux signal (politesse, biais de désirabilité sociale) ?"]}}},maps:{universel:{viewBox:"0 0 820 280",nodes:[{id:"utilisateurAcheteurDecideur",x:20,y:108,w:155,h:65},{id:"jobsToBeDone",x:225,y:40,w:140,h:65},{id:"contexteUsage",x:225,y:175,w:130,h:65},{id:"hypothesesFaits",x:430,y:108,w:130,h:65},{id:"validerSansProduit",x:620,y:108,w:140,h:65}],edges:[{x1:175,y1:128,x2:223,y2:78,label:"définit"},{x1:175,y1:148,x2:223,y2:195,label:"situe"},{x1:365,y1:72,x2:428,y2:128,label:"génère"},{x1:355,y1:208,x2:428,y2:152,label:"contraint"},{x1:560,y1:140,x2:618,y2:140,label:"teste"}]}}}),r=e({id:"conception-C03",number:13,title:"La Solution et le Périmètre",subtitle:"Passer du problème validé à une solution délimitée et testable",badge:"Fiche C03 — Vision Systémique",meta:["5 nœuds · universel"],readingTime:"20 min",description:"Comprendre le problème et connaître ses utilisateurs ne suffit pas — il faut encore décider quoi construire, et surtout quoi ne pas construire. Cette fiche donne les outils pour concevoir une solution comme une hypothèse testable, délimiter un périmètre réaliste, et éviter les pièges classiques du feature creep et du sur-engineering.",accent:"decision",nodes:{desirableFaisableViable:{id:"desirableFaisableViable",label:"Désirable / Faisable / Viable",icon:"△",kind:"modele",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>La plupart des produits ratent parce qu'ils optimisent une seule dimension. <strong>Désirable mais pas viable</strong> : les utilisateurs adorent mais personne ne peut le rentabiliser. <strong>Viable mais pas désirable</strong> : le modèle économique tient mais personne ne veut le produit. <strong>Faisable mais ni désirable ni viable</strong> : prouesse technique sans marché. Le triangle de l'innovation (IDEO) pose que la bonne solution se situe à l'intersection des trois.</p>",system:`<p>Ce nœud est le cadre de référence de toute la fiche C03. Il synthétise le problème réel <span class="ref-fiche">→ C01</span> (désirable : la douleur existe) et les utilisateurs <span class="ref-fiche">→ C02</span> (désirable : le bon segment en a besoin dans son contexte). Il conditionne <strong>Le vrai MVP</strong> (qu'est-ce qui est faisable rapidement et encore viable ?), <strong>La contrainte créatrice</strong> (comment rendre faisable ce qui est désirable), et <strong>Ce qu'on ne construit pas</strong> (ce qui n'est pas encore faisable ou viable).</p>`,choice:{kind:"free",html:`<p>Le triangle désirable/faisable/viable est le cadre le plus utilisé, mais d'autres grilles existent :</p>
<p><strong>Now / Next / Later :</strong> priorisation par horizon temporel. Ce qui est désirable, faisable et viable maintenant ; ce qui le deviendra ; ce qui reste incertain. Utile pour roadmapper sans s'engager sur des détails lointains.</p>
<p><strong>RICE (Reach × Impact × Confidence ÷ Effort) :</strong> scoring quantitatif de features. Utile pour arbitrer entre plusieurs options toutes désirables/faisables/viables.</p>
<p><strong>Kano model :</strong> distingue les features de base (attendues), de performance (plus il y en a, mieux c'est), et d'enchantement (inattendues et délightantes). Utile pour hiérarchiser au sein du périmètre.</p>
<p><strong>Règle :</strong> utilise désirable/faisable/viable pour valider qu'une solution mérite d'être construite. Utilise les autres cadres pour arbitrer entre solutions déjà validées.</p>`},senior:"<p>Un product manager expérimenté utilise ce cadre comme un filtre continu, pas comme un exercice ponctuel. <strong>À chaque décision produit, il se demande : est-ce que ça renforce la désirabilité, la faisabilité, ou la viabilité — ou est-ce que ça fragilise l'une d'elles ?</strong> Une feature qui augmente la désirabilité mais rend le produit infaisable dans les délais n'est pas une bonne feature, même si elle est belle.</p><p>Il sait aussi que les trois dimensions évoluent dans le temps : ce qui est infaisable aujourd'hui peut devenir faisable dans six mois (nouvelle techno, équipe plus grande).</p>",errors:`<p><strong>Pattern 1 — La désirabilité assumée :</strong> on investit dans la faisabilité et la viabilité sans avoir validé la désirabilité. Le produit est techniquement réalisable et économiquement viable, mais personne n'en veut. L'ordre compte : désirabilité d'abord, puis faisabilité, puis viabilité.</p>
<p><strong>Pattern 2 — La viabilité oubliée :</strong> on construit quelque chose que les utilisateurs adorent, mais sans modèle économique. L'acquisition est gratuite, le support coûteux, la monétisation absente. Le produit est une charge, pas un actif.</p>
<p><strong>Pattern 3 — La faisabilité surpondérée :</strong> on réduit le périmètre au point où le produit est techniquement facile mais ne résout plus vraiment le problème. On a un produit 'livrable' mais inutile.</p>`,invariants:"<p>Les outils de design thinking changent. <strong>Ce qui ne change pas : une solution durable doit être voulue par les utilisateurs, réalisable avec les moyens disponibles, et rentable pour l'organisation qui la produit. L'absence d'une de ces trois conditions condamne le produit tôt ou tard.</strong></p><p><strong>Ce qui change :</strong> les méthodes pour évaluer chaque dimension. <strong>Ce qui ne change pas :</strong> la nécessité d'évaluer les trois avant de s'engager dans la construction.</p>",practice:{exercices:[{titre:"Évaluer une solution sur les trois dimensions",etapes:["Choisis une solution ou un produit que tu veux construire (ou un existant que tu veux analyser).","Pour la désirabilité : liste les preuves que des utilisateurs réels veulent cette solution. Qu'est-ce qui manque comme preuve ?","Pour la faisabilité : liste les contraintes techniques, humaines, et temporelles. Qu'est-ce qui pourrait rendre la solution infaisable ?","Pour la viabilité : esquisse le modèle économique. Comment génère-t-on assez de valeur pour couvrir les coûts et croître ?","Identifie la dimension la plus fragile et formule une action pour la renforcer."],output:"Un tableau désirable/faisable/viable avec preuves et lacunes pour chaque dimension, et une action prioritaire identifiée.",critere:"Tu as identifié au moins une lacune par dimension. Si tout te paraît solide sur les trois dimensions, tu n'as pas été assez critique ou tu travailles sur un marché très bien connu."}],piege:"Évaluer les trois dimensions en silo plutôt que comme un système. Une décision qui renforce la désirabilité peut fragiliser la faisabilité (plus de features = plus de complexité). Les trois dimensions s'influencent mutuellement."},verification:["Explique dans tes mots ce que signifient désirable, faisable, et viable pour un produit.","Un produit de fitness tracking est désirable (les gens veulent se suivre) et faisable (la tech existe) mais pas encore viable. Quelles sont les causes possibles ? Comment y remédier ?","Pourquoi l'ordre désirabilité → faisabilité → viabilité est-il important ? Que se passe-t-il si on commence par la viabilité ?"]}},vraiMvp:{id:"vraiMvp",label:"Le vrai MVP",icon:"🚀",kind:"decision",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:"<p>Beaucoup d'équipes appellent MVP une version pauvre d'un produit complet : moins belle, moins stable, moins riche. Elles livrent alors quelque chose qui coûte cher, déçoit les utilisateurs, et n'apprend pas grand-chose. <strong>Pour Eric Ries, un MVP est l'expérience la plus légère qui permet de valider les hypothèses critiques du business.</strong> Ce n'est pas un produit dégradé — c'est parfois un email, une landing page, ou une conversation.</p>",system:`<p>Le vrai MVP est l'application opérationnelle de <strong>Désirable/Faisable/Viable</strong> (qu'est-ce qu'on peut construire rapidement pour valider les trois dimensions ?) et de <strong>Valider sans produit</strong> <span class="ref-fiche">→ C02</span> (les méthodes les plus légères viennent avant le code). Il alimente directement la mesure <span class="ref-fiche">→ C06</span> : un MVP sans métriques de validation n'est pas un MVP, c'est une version alpha.</p>`,choice:{kind:"free",html:`<p>Le spectre des MVPs, du plus léger au plus élaboré :</p>
<p><strong>Entretien + démo fictive :</strong> montrer un prototype non fonctionnel pour valider la compréhension et l'intérêt. Zéro code, feedback en quelques jours.</p>
<p><strong>Landing page + pre-signup :</strong> mesurer l'intent avant de construire. Une semaine de travail, signal quantitatif sur la désirabilité.</p>
<p><strong>Concierge MVP :</strong> faire manuellement ce que le produit ferait automatiquement. Valide la valeur proposée sans infrastructure. Classique pour les marketplaces.</p>
<p><strong>Single feature MVP :</strong> une seule feature qui résout le problème principal. Tout le reste est hors scope jusqu'à validation de cette feature.</p>
<p><strong>Règle :</strong> un MVP est réussi s'il invalide ou confirme l'hypothèse la plus critique du projet. S'il ne peut pas faire ça, ce n'est pas un MVP — c'est une version bêta.</p>`},senior:"<p>Un product manager expérimenté demande toujours : <strong>quelle est l'hypothèse critique que ce MVP doit tester ?</strong> Sans réponse précise à cette question, on construit quelque chose mais on n'apprend rien. Il définit aussi à l'avance ce qui constituerait un succès — quel chiffre, quel comportement, quel signal — avant de lancer le MVP, pour éviter l'interprétation biaisée des résultats.</p>",errors:`<p><strong>Pattern 1 — Le MVP qui n'est pas minimum :</strong> six mois de développement pour "valider" une idée. Ce n'est pas un MVP, c'est un produit complet avec moins de polish. Si la construction du MVP prend plus d'un mois, repose-toi la question de ce qu'on essaie de valider.</p>
<p><strong>Pattern 2 — Le MVP sans hypothèse :</strong> on construit quelque chose, on le lance, et on "voit ce qui se passe". Sans hypothèse définie à l'avance, n'importe quel résultat est interprétable comme une validation. Les données sans question préalable ne signifient rien.</p>
<p><strong>Pattern 3 — La mauvaise métrique de succès :</strong> on mesure ce qui est facile à mesurer (téléchargements, inscriptions) plutôt que ce qui valide l'hypothèse (rétention, willingness to pay, NPS). Un MVP peut avoir 10 000 inscriptions et invalider l'hypothèse centrale.</p>`,invariants:"<p>Les technologies pour construire des MVPs changent (no-code, IA, templates). <strong>Ce qui ne change pas : la valeur d'un MVP est dans l'apprentissage qu'il génère, pas dans le produit qu'il livre. Un MVP qui ne génère pas d'apprentissage actionnable est du gaspillage, quelle que soit sa qualité technique.</strong></p><p><strong>Ce qui change :</strong> la facilité de construire des MVPs (no-code a rendu beaucoup de tests accessibles). <strong>Ce qui ne change pas :</strong> la nécessité de définir l'hypothèse et le critère de succès avant de construire.</p>",practice:{exercices:[{titre:"Concevoir le MVP le plus léger possible",etapes:["Formule l'hypothèse critique de ton projet : 'Je crois que [segment] a [problème] et paierait [montant] pour [solution].'","Identifie le signal qui validerait ou invaliderait cette hypothèse.","Propose trois versions de MVP du plus léger au plus élaboré. Pour chacune, estime : temps de construction, qualité du signal obtenu, et coût si l'hypothèse est fausse.","Choisis la version qui donne le signal le plus fiable au coût le plus faible."],output:"Trois versions de MVP comparées sur temps/signal/coût, avec le choix justifié.",critere:"La version choisie peut être construite en moins de deux semaines et donne un signal qui invaliderait clairement l'hypothèse si le résultat est négatif. Si la version 'légère' prend plus d'un mois, tu n'es pas encore au niveau MVP."}],piege:"Confondre MVP (minimum viable product pour apprendre) avec MMP (minimum marketable product — le minimum pour vendre). Un MVP n'est pas forcément commercialisable. Il peut être moche, limité, et nécessiter une intervention humaine — tant qu'il valide l'hypothèse."},verification:["Quelle est la définition correcte d'un MVP ? En quoi diffère-t-elle de 'produit avec peu de features' ?","Tu veux valider si des restaurateurs paieraient pour un outil de gestion des réservations. Propose un MVP qui ne nécessite pas de code.","Pourquoi définir le critère de succès avant de lancer le MVP est-il critique ?"]}},contrainteCreatrice:{id:"contrainteCreatrice",label:"La contrainte créatrice",icon:"⚡",kind:"decision",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:"<p>L'absence de contrainte produit de la médiocrité — trop d'options, trop de temps, trop de budget mènent à des produits complexes et peu différenciés. <strong>Les contraintes forcent à faire des choix, et les choix forcent à trouver des solutions créatives que l'abondance ne génère jamais.</strong> Twitter a limité à 140 caractères par contrainte technique — cette contrainte est devenue la définition du produit.</p>",system:`<p>La contrainte créatrice est le mécanisme qui rend <strong>Le vrai MVP</strong> possible — si on avait du temps et des ressources illimitées, on ne serait jamais forcé de choisir l'essentiel. Elle s'articule avec <strong>Ce qu'on ne construit pas</strong> (la contrainte définit ce qu'on exclut), avec <strong>Désirable/Faisable/Viable</strong> (la contrainte agit sur la faisabilité), et avec la priorisation <span class="ref-fiche">→ C05</span>, parce qu'une contrainte explicite transforme les préférences en arbitrages.</p>`,choice:{kind:"free",html:`<p>Les contraintes utiles en design de produit :</p>
<p><strong>Contrainte de temps :</strong> un délai serré force à identifier l'essentiel. "Qu'est-ce qu'on peut livrer en 4 semaines ?" est une meilleure question que "qu'est-ce qu'on devrait construire ?"</p>
<p><strong>Contrainte d'équipe :</strong> une petite équipe force la priorisation. Une seule personne ne peut pas tout construire — elle construit ce qui compte le plus.</p>
<p><strong>Contrainte de budget :</strong> elle force à trouver des solutions créatives plutôt que de jeter de l'argent sur les problèmes.</p>
<p><strong>Contrainte d'interface :</strong> "une seule page", "un seul bouton", "dix mots maximum" sont des contraintes qui forcent à trouver la solution la plus claire possible.</p>`},senior:`<p>Un product manager expérimenté utilise les contraintes comme un outil de design intentionnel, pas seulement comme une réalité subie. <strong>Il pose des contraintes volontaires même quand les ressources ne l'exigent pas</strong>, parce qu'il sait que l'abondance produit de la complexité et que la complexité est l'ennemie de l'adoption. Il demande régulièrement : "Si on ne pouvait construire qu'une seule chose, ce serait quoi ?"</p>`,errors:`<p><strong>Pattern 1 — La contrainte cachée :</strong> la contrainte existe (budget limité, deadline serrée) mais n'est pas rendue explicite à l'équipe. L'équipe continue à penser en abondance alors qu'elle devrait penser en contrainte. Résultat : un scope trop large, livré en retard et en dessous des attentes.</p>
<p><strong>Pattern 2 — La contrainte injustifiée :</strong> on impose une contrainte sans expliquer pourquoi, l'équipe la perçoit comme arbitraire et cherche à la contourner. Une contrainte comprise est une contrainte utile — une contrainte incomprise est une friction.</p>
<p><strong>Pattern 3 — La sur-contrainte :</strong> on restreint tellement le périmètre que le produit ne résout plus le problème réel. La contrainte doit forcer à choisir l'essentiel, pas à amputer le cœur du produit.</p>`,invariants:"<p>Les contraintes spécifiques changent selon les contextes et les époques. <strong>Ce qui ne change pas : la créativité naît de la contrainte, pas de l'abondance. Les meilleurs produits sont ceux qui ont fait des choix radicaux, pas ceux qui ont essayé de tout faire.</strong></p><p><strong>Ce qui change :</strong> la nature des contraintes (temps, argent, techno, marché). <strong>Ce qui ne change pas :</strong> l'effet de la contrainte sur la qualité des décisions — elle force à aller à l'essentiel.</p>",practice:{exercices:[{titre:"Appliquer une contrainte radicale",etapes:["Prends un projet ou une idée de produit avec son périmètre actuel.","Applique la contrainte : 'si on ne peut construire qu'une seule feature, ce serait laquelle ?'","Justifie ton choix : pourquoi cette feature et pas une autre ? Quel problème résout-elle en priorité ?","Maintenant applique la contrainte inverse : 'si on devait retirer une feature et n'en garder que les autres, laquelle retire-t-on en premier ?' Répète jusqu'à ce qu'il ne reste qu'une feature.","Compare les deux résultats : sont-ils cohérents ? Si non, qu'est-ce que ça révèle sur tes priorités ?"],output:"Une feature principale identifiée par deux méthodes de contrainte, avec la justification et l'analyse des éventuelles incohérences.",critere:"Les deux méthodes convergent vers la même feature ou révèlent une tension réelle dans les priorités. Si tu n'arrives pas à choisir une seule feature, c'est que le problème n'est pas encore assez bien défini."}],piege:"Choisir la feature la plus facile à construire plutôt que la plus importante pour l'utilisateur. La contrainte doit forcer à identifier l'essentiel, pas à optimiser pour la facilité d'implémentation."},verification:["Pourquoi les contraintes de ressources mènent-elles souvent à de meilleures décisions produit que l'abondance ?","Twitter a imposé une limite de 140 caractères. Comment cette contrainte a-t-elle défini le produit plutôt que de le limiter ?","Quelle est la différence entre une contrainte créatrice et une contrainte paralysante ? Comment distinguer les deux ?"]}},ceQuOnNeConstructPas:{id:"ceQuOnNeConstructPas",label:"Ce qu'on ne construit pas",icon:"🚫",kind:"decision",osLabel:"Universel",niveau:"Fondation",sections:{why:`<p>Une demande d'utilisateur paraît souvent raisonnable quand elle arrive seule. Dix demandes raisonnables plus tard, le produit a perdu son identité : il fait un peu de tout, lentement, avec une interface que personne ne comprend. <strong>Sans frontière explicite, le périmètre s'étend naturellement.</strong> Le "non" est une décision de design au même titre que le "oui".</p>`,system:`<p>Ce nœud est le complément indispensable de <strong>Le vrai MVP</strong> (le MVP est défini autant par ce qu'il exclut que par ce qu'il inclut) et de <strong>La contrainte créatrice</strong> (la contrainte force à exclure). Il prépare la priorisation <span class="ref-fiche">→ C05</span> : décider ce qu'on ne fait pas est la première étape de toute priorisation saine.</p>`,choice:{kind:"free",html:`<p>Plusieurs approches pour délimiter le périmètre :</p>
<p><strong>La liste de non-scope explicite :</strong> à côté de la roadmap, une liste de ce qui ne sera jamais dans ce produit (ou pas avant très longtemps). Force l'équipe à avoir la conversation difficile.</p>
<p><strong>Les "won't do" dans le backlog :</strong> certaines équipes agile maintiennent un backlog de tickets explicitement rejetés avec la raison du refus. Permet de ne pas réexpliquer la même décision vingt fois.</p>
<p><strong>Le principe de Jason Fried (Basecamp) :</strong> le périmètre est toujours trop large. La question n'est pas "qu'est-ce qu'on ajoute ?" mais "qu'est-ce qu'on retire pour que le reste soit excellent ?"</p>`},senior:"<p>Un product manager expérimenté considère chaque demande de feature comme potentiellement hors scope jusqu'à preuve du contraire. <strong>Il distingue les demandes qui résolvent le problème central du produit et les demandes qui étendent le problème que le produit cherche à résoudre.</strong> Étendre le problème sans valider la nouvelle direction est du feature creep, même si chaque demande individuelle semble raisonnable.</p><p>Il documente aussi les refus — non pas pour dire non définitivement, mais pour avoir un historique des décisions et des raisons qui les ont motivées.</p>",errors:`<p><strong>Pattern 1 — Le feature creep du client :</strong> un client important demande une feature spécifique à son usage, l'équipe la construit, et ça crée un précédent. D'autres clients demandent leurs propres features spécifiques. Le produit devient une accumulation de besoins individuels sans cohérence.</p>
<p><strong>Pattern 2 — Le "on le fera plus tard" :</strong> on ne dit jamais vraiment non, on dit "c'est dans la roadmap". Le résultat est un backlog infini que personne ne regarde vraiment et une équipe qui ne sait pas ce qui compte vraiment.</p>
<p><strong>Pattern 3 — Le scope qui s'étend en cours de sprint :</strong> une feature "simple" révèle des cas limites pendant le développement, l'équipe les traite au fil de l'eau, et la feature triple en complexité. Sans discipline de scope, chaque sprint finit en dépassement.</p>`,invariants:"<p>Les méthodes de gestion de backlog et de roadmap changent. <strong>Ce qui ne change pas : la liste de ce qu'on ne construit pas est aussi importante que la liste de ce qu'on construit. Un produit sans frontière claire n'a pas d'identité, et un produit sans identité n'a pas d'utilisateurs fidèles.</strong></p><p><strong>Ce qui change :</strong> les outils de gestion de roadmap et de backlog. <strong>Ce qui ne change pas :</strong> la nécessité humaine et organisationnelle de dire non pour dire oui à ce qui compte vraiment.</p>",practice:{exercices:[{titre:"Construire la liste de non-scope",etapes:["Pour un produit ou projet réel (ou imaginé), liste 10 features qui pourraient être demandées ou souhaitées.","Pour chaque feature, réponds : est-ce que ça résout le problème central que ce produit cherche à résoudre ?","Classe les 10 features en trois catégories : In scope (résout le problème central), Hors scope pour l'instant (peut être revisité plus tard), Hors scope définitif (n'appartient pas à ce produit).","Pour les deux catégories 'hors scope', formule la raison — ce n'est pas 'on n'a pas le temps' mais 'ça diluerait notre focus sur X' ou 'ça résout un problème différent'."],output:"Une liste de 10 features triées en trois catégories, avec une justification pour les hors-scope.",critere:"Au moins 3 features sont classées hors scope définitif, avec des justifications liées à la vision produit et non aux ressources. Si tout est 'in scope', le périmètre n'est pas délimité."}],piege:"Classer hors scope uniquement les features difficiles à construire. Le périmètre doit être délimité par la cohérence avec le problème central, pas par la complexité technique. Certaines features faciles à construire sont hors scope parce qu'elles diluent le focus."},verification:["Pourquoi définir ce qu'un produit ne fait pas est-il aussi important que définir ce qu'il fait ?","Un utilisateur clé te demande une feature d'import CSV. Comment décides-tu si c'est in scope ou hors scope ?","Quelle est la différence entre 'on le fera plus tard' et 'c'est hors scope' ? Pourquoi l'ambiguïté est-elle dangereuse ?"]}},solutionHypothese:{id:"solutionHypothese",label:"La solution comme hypothèse",icon:"🔬",kind:"validation",osLabel:"Universel",niveau:"Fondation",sections:{why:`<p>On traite souvent une solution comme une réponse — quelque chose qu'on construit une fois qu'on a compris le problème. <strong>Une solution est toujours une hypothèse : "je crois que X résoudra le problème Y pour les utilisateurs Z."</strong> Traiter la solution comme une certitude, c'est s'interdire de l'invalider et de s'adapter. Traiter la solution comme une hypothèse, c'est maintenir l'ouverture nécessaire pour apprendre et pivoter.</p>`,system:`<p>Ce nœud est la charnière entre C03 et la mesure <span class="ref-fiche">→ C06</span>. Il s'appuie sur <strong>Désirable/Faisable/Viable</strong> (les trois dimensions de l'hypothèse), <strong>Le vrai MVP</strong> (le test minimal de l'hypothèse), et prépare les métriques de C06, qui valident ou invalident l'hypothèse de solution. Il est aussi lié à la priorisation <span class="ref-fiche">→ C05</span> : on priorise les hypothèses à tester, pas les features à construire.</p>`,choice:{kind:"free",html:`<p>Différentes façons de formuler et tester une hypothèse de solution :</p>
<p><strong>Format "we believe that" :</strong> "We believe that [solution] will result in [outcome] for [users]. We will know we're right when [measurable signal]." Rend l'hypothèse explicite et testable.</p>
<p><strong>Lean hypothesis statement :</strong> similaire, issu du lean startup. L'important est la partie "we will know we're right when" — sans signal de validation défini, l'hypothèse n'est pas testable.</p>
<p><strong>Falsifiabilité de Popper :</strong> une hypothèse scientifique n'est valide que si elle peut être réfutée. Le même principe s'applique aux hypothèses produit — si tu ne peux pas imaginer un résultat qui prouverait que la solution est fausse, c'est une croyance, pas une hypothèse.</p>`},senior:`<p>Un product manager expérimenté traite chaque feature comme un test. <strong>Avant de commencer le développement, il formule l'hypothèse que la feature teste, et il définit à l'avance ce qui constituerait un succès ou un échec.</strong> Cela lui permet de couper des features qui ne performent pas sans attaches émotionnelles — ce n'est pas un échec, c'est un apprentissage.</p><p>Il maintient aussi une "solution hypothesis log" — un historique des hypothèses testées, des résultats, et des décisions prises. Ça évite de retester les mêmes hypothèses et de rejouer les mêmes débats.</p>`,errors:`<p><strong>Pattern 1 — Le sunk cost de la solution :</strong> on a investi du temps dans une solution, elle ne performe pas, mais on continue à l'améliorer plutôt que de l'invalider. L'investissement passé n'est pas une raison de continuer — il est perdu dans tous les cas.</p>
<p><strong>Pattern 2 — La solution sans signal de validation :</strong> on lance une feature sans définir à l'avance ce qui constituerait un succès. Après le lancement, n'importe quel chiffre est interprétable comme un succès avec un peu de bonne volonté.</p>
<p><strong>Pattern 3 — L'hypothèse non formulée :</strong> l'équipe a une solution en tête mais ne l'a jamais explicitement formulée comme hypothèse. Du coup, personne ne remet en question le fait que c'est la bonne solution — c'est juste "la solution".</p>`,invariants:"<p>Les frameworks de gestion des hypothèses changent. <strong>Ce qui ne change pas : toute solution est une hypothèse sur la façon de résoudre un problème. La différence entre une équipe qui apprend vite et une équipe qui patine est la clarté avec laquelle elle formule et teste ses hypothèses.</strong></p><p><strong>Ce qui change :</strong> les outils de test et de mesure. <strong>Ce qui ne change pas :</strong> la relation causale entre une hypothèse claire, un test rigoureux, et un apprentissage actionnable.</p>",practice:{exercices:[{titre:"Formuler une hypothèse de solution complète",etapes:["Choisis une solution ou feature que tu veux construire.","Formule l'hypothèse complète : 'Je crois que [description de la solution] résoudra [problème spécifique] pour [segment d'utilisateurs].'","Formule le signal de validation : 'Je saurai que j'ai raison quand [métrique] atteindra [seuil] en [délai].'","Formule le signal d'invalidation : 'Je saurai que j'ai tort quand [métrique] ne dépasse pas [seuil] en [délai].'","Identifie ce que tu ferais si l'hypothèse est invalidée : pivoter (changer la solution), persévérer (corriger l'exécution), ou arrêter (abandonner l'idée)."],output:"Une hypothèse de solution complète avec signal de validation, signal d'invalidation, et plan de réponse en cas d'invalidation.",critere:"Le signal d'invalidation est aussi précis que le signal de validation — tu peux imaginer les deux résultats clairement. Si l'invalidation semble impossible ou improbable, l'hypothèse n'est pas assez honnêtement formulée."}],piege:"Formuler des hypothèses trop vagues pour être invalidées : 'les utilisateurs seront plus satisfaits' n'est pas un signal de validation. Un signal doit être mesurable, temporellement borné, et suffisamment précis pour trancher."},verification:["Pourquoi traiter une solution comme une hypothèse plutôt que comme une réponse change-t-il l'approche du développement ?","Formule une hypothèse complète pour une feature de notification push dans une app de recettes. Inclus le signal de validation et d'invalidation.","Qu'est-ce que la falsifiabilité ? Pourquoi une hypothèse non falsifiable est-elle inutile pour guider les décisions produit ?"]}}},maps:{universel:{viewBox:"0 0 820 280",nodes:[{id:"desirableFaisableViable",x:20,y:108,w:155,h:65},{id:"vraiMvp",x:230,y:40,w:120,h:65},{id:"contrainteCreatrice",x:230,y:175,w:140,h:65},{id:"ceQuOnNeConstructPas",x:430,y:108,w:150,h:65},{id:"solutionHypothese",x:640,y:108,w:150,h:65}],edges:[{x1:175,y1:125,x2:228,y2:78,label:"délimite"},{x1:175,y1:150,x2:228,y2:195,label:"force"},{x1:350,y1:72,x2:428,y2:128,label:"précise"},{x1:370,y1:208,x2:428,y2:152,label:"exclut"},{x1:580,y1:140,x2:638,y2:140,label:"teste"}]}}}),o=e({id:"conception-C04",number:14,title:"La Viabilité et les Risques",subtitle:"Évaluer si une opportunité peut devenir un projet durable",badge:"Fiche C04 — Vision Systémique",meta:["5 nœuds · universel"],readingTime:"25 min",description:"Comprendre la taille du marché, les alternatives existantes, le modèle économique, les risques et les critères qui justifient parfois de ne pas construire.",accent:"diagnostic",nodes:{leMarche:{id:"leMarche",label:"Le marché",icon:"📊",kind:"diagnostic",osLabel:"Universel",niveau:"Fondation",sections:{why:`<p>Une douleur réelle peut exister chez dix personnes, et rester un très mauvais projet. Le piège consiste à confondre "quelqu'un a ce problème" avec "il existe assez de personnes atteignables, solvables, et motivées pour soutenir un produit". <strong>Le marché sert à vérifier si le problème dépasse l'anecdote.</strong> Sans cette vérification, on peut construire une solution utile pour un micro-segment impossible à atteindre ou trop petit pour payer les coûts du produit.</p>`,system:'<p>Le marché prolonge <strong>Douleur vs Préférence</strong> <span class="ref-fiche">→ C01</span> : une douleur forte ne suffit que si elle touche un segment assez large ou assez précieux. Il dépend des rôles <strong>Utilisateur / Acheteur / Décideur</strong> <span class="ref-fiche">→ C02</span>, car le marché réel est celui qui peut acheter, pas seulement utiliser. Il conditionne ensuite les modèles économiques de cette fiche et les arbitrages de priorisation <span class="ref-fiche">→ C05</span>.</p>',choice:{kind:"structured",main:"<p>Il existe plusieurs façons d'estimer un marché. Le bon choix dépend du stade du projet et du niveau d'incertitude.</p>",alternatives:[{name:"TAM / SAM / SOM",description:"Utile pour cadrer l'ordre de grandeur. Bon pour communiquer avec investisseurs ou dirigeants, dangereux si les chiffres restent top-down et non reliés à un segment atteignable."},{name:"Bottom-up par segment",description:"Partir d'un segment précis, du nombre d'acteurs, du prix possible et du taux d'adoption réaliste. Moins impressionnant, mais beaucoup plus fiable pour décider quoi construire."},{name:"Marchés analogues",description:"Comparer avec un marché voisin quand la catégorie est nouvelle. Utile pour générer une hypothèse, jamais suffisant comme preuve."}]},senior:`<p>Un product manager expérimenté se méfie des grands chiffres. Un marché de 10 milliards peut être inutilisable si le canal d'accès est verrouillé, si les cycles d'achat durent 18 mois, ou si les budgets sont capturés par des acteurs installés. <strong>Il regarde d'abord le marché accessible maintenant, pas le marché théorique total.</strong> Sa question mentale : "avec nos ressources actuelles, quel segment précis peut-on atteindre et convaincre dans les 90 prochains jours ?"</p>`,errors:"<p><strong>Pattern 1 — Le TAM hypnotique :</strong> on cite un marché énorme pour se rassurer, sans montrer quelle part est réellement atteignable. Le grand chiffre masque l'absence de stratégie d'accès.</p><p><strong>Pattern 2 — Le segment élastique :</strong> dès que les chiffres sont trop petits, on élargit la cible jusqu'à ce qu'elle paraisse assez grande. Le marché devient impressionnant mais le produit devient flou.</p><p><strong>Pattern 3 — Le marché sans canal :</strong> on prouve que les clients existent, mais pas qu'on peut les atteindre. Un marché inaccessible est équivalent à un marché inexistant pour une petite équipe.</p>",invariants:"<p>Un marché utile est un marché segmenté, atteignable et solvable. Un chiffre global ne devient une décision que lorsqu'il est relié à un canal, un prix, et un comportement d'achat plausible. <strong>Ce qui change :</strong> les sources de données, les catégories de marché et les canaux d'acquisition. <strong>Ce qui ne change pas :</strong> une opportunité viable exige un segment réel que l'équipe peut atteindre, convaincre et servir avec ses moyens.</p>",practice:{exercices:[{titre:"Estimer un marché accessible",etapes:["Définis un segment cible en une phrase précise : type d'utilisateur, contexte, douleur, capacité de paiement.","Estime le nombre d'acteurs dans ce segment avec au moins deux sources ou approximations explicites.","Déduis le marché accessible à 12 mois : combien peux-tu réellement contacter, convaincre, convertir et servir ?","Compare ce chiffre au marché total annoncé et note l'écart entre ambition et accessibilité."],output:"Une estimation TAM/SAM/SOM ou bottom-up avec segment, sources, hypothèses de conversion et marché accessible à 12 mois.",critere:"Une autre personne doit pouvoir modifier une hypothèse et recalculer ton estimation. Si ton chiffre final ne dépend d'aucune hypothèse visible, il n'est pas auditable."}],piege:"Commencer par Google et chercher le plus gros chiffre disponible. Le bon ordre est inverse : segment réel, canal réel, prix plausible, puis seulement taille totale."},verification:["Pourquoi une douleur réelle ne suffit-elle pas à prouver qu'il existe un marché viable ?","Tu identifies 200 cabinets médicaux qui ont exactement le problème que tu résous, mais ils sont difficiles à contacter et ont peu de budget. Comment analyses-tu ce marché ?","Quel invariant distingue un marché théorique d'un marché accessible ?"]}},concurrenceInfo:{id:"concurrenceInfo",label:"La concurrence comme information",icon:"🔭",kind:"diagnostic",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:`<p>Quand une équipe dit "nous n'avons pas de concurrents", elle révèle souvent qu'elle n'a pas compris le comportement actuel des utilisateurs. Les gens résolvent déjà leurs problèmes, même mal : tableurs, emails, WhatsApp, assistants humains, renoncement. <strong>La concurrence n'est pas seulement les produits similaires ; c'est tout ce que l'utilisateur utilise à la place du changement.</strong></p>`,system:`<p>Ce nœud complète l'analyse du marché : les concurrents indiquent que le problème est déjà reconnu, mais aussi que l'accès au marché a un coût. Il dépend des <strong>Jobs-to-be-done</strong> <span class="ref-fiche">→ C02</span>, car les vrais concurrents sont ceux qui accomplissent le même job. Il informe le périmètre <span class="ref-fiche">→ C03</span> : se différencier ne signifie pas ajouter plus, mais choisir quelle frustration concurrente résoudre mieux.</p>`,choice:{kind:"structured",main:"<p>L'analyse concurrentielle peut servir trois objectifs différents. Les mélanger produit des conclusions floues.</p>",alternatives:[{name:"Alternatives comportementales",description:"Observer ce que les utilisateurs font aujourd'hui. Indispensable en early stage, car c'est la concurrence la plus réelle."},{name:"Concurrents directs",description:"Comparer les produits de la même catégorie. Utile pour comprendre les standards, le pricing et les attentes minimales."},{name:"Avis négatifs et churn public",description:"Lire les frustrations récurrentes. Très utile pour trouver une différenciation, à condition de vérifier que ces plaintes viennent du segment ciblé."}]},senior:`<p>Un product manager expérimenté ne cherche pas seulement "qui fait pareil". Il cherche "qu'est-ce que l'utilisateur devrait abandonner pour nous adopter ?" <strong>Le concurrent le plus dangereux est souvent l'habitude actuelle, pas la startup voisine.</strong> Il sait aussi qu'une plainte concurrente n'est pas automatiquement une opportunité : certaines frustrations sont le prix acceptable d'un autre bénéfice plus important.</p>`,errors:'<p><strong>Pattern 1 — Le concurrent cosmétique :</strong> on compare les interfaces et les features, mais pas le job accompli. On copie la surface sans comprendre pourquoi les utilisateurs restent.</p><p><strong>Pattern 2 — Le mépris du bricolage :</strong> on ignore Excel, email ou papier parce que ce ne sont pas des "vrais produits". Pourtant ces bricolages prouvent ce que les utilisateurs tolèrent et refusent.</p><p><strong>Pattern 3 — La différenciation décorative :</strong> on ajoute une feature différente pour être différent, sans résoudre une frustration importante. La différence devient marketing, pas adoption.</p>',invariants:"<p>Tout produit remplace un comportement existant. Même une catégorie nouvelle entre en concurrence avec l'inaction, les habitudes et les solutions imparfaites. <strong>Ce qui change :</strong> les acteurs, les catégories et les interfaces concurrentes. <strong>Ce qui ne change pas :</strong> pour adopter une solution, l'utilisateur doit abandonner quelque chose qui fonctionne déjà assez bien pour lui.</p>",practice:{exercices:[{titre:"Cartographier la concurrence réelle",etapes:["Choisis un problème utilisateur précis et liste cinq façons actuelles de le gérer, produits ou bricolages inclus.","Pour chaque alternative, note ce qu'elle fait bien, ce qu'elle fait mal, et pourquoi les utilisateurs la gardent malgré ses défauts.","Lis au moins dix avis ou témoignages négatifs sur deux alternatives et regroupe les frustrations récurrentes.","Formule une différenciation qui répond à une frustration importante sans perdre le bénéfice qui retient les utilisateurs aujourd'hui."],output:"Une carte des alternatives actuelles avec bénéfices, frustrations, inerties et une hypothèse de différenciation.",critere:"Ta différenciation doit expliquer pourquoi l'utilisateur changerait maintenant. Si elle se résume à 'plus simple' ou 'plus moderne', elle est trop faible."}],piege:"Ne regarder que les concurrents directs visibles sur Google. Les alternatives les plus instructives sont souvent les outils pauvres mais profondément intégrés dans le quotidien."},verification:["Pourquoi Excel ou WhatsApp peuvent-ils être de vrais concurrents d'un produit SaaS ?","Tu lis 50 avis négatifs sur un concurrent. Comment distingues-tu une opportunité d'une frustration acceptable par le marché ?","Quel invariant explique pourquoi 'nous n'avons pas de concurrents' est presque toujours faux ?"]}},modelesEconomiques:{id:"modelesEconomiques",label:"Modèles économiques",icon:"💰",kind:"modele",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:"<p>Un produit peut créer de la valeur et mourir quand même. Si personne ne paie, si le coût de servir l'utilisateur dépasse la valeur capturée, ou si le modèle pousse à dégrader l'expérience, la solution n'est pas durable. <strong>Le modèle économique force à expliciter qui paie, pour quelle valeur, à quel moment, et avec quels coûts cachés.</strong></p>",system:`<p>Le modèle économique relie les rôles utilisateur/acheteur/décideur <span class="ref-fiche">→ C02</span> à la viabilité : celui qui paie n'est pas toujours celui qui reçoit la valeur directe. Il contraint le périmètre <span class="ref-fiche">→ C03</span>, car une feature gratuite mais coûteuse en support peut rendre le produit non viable. Il détermine aussi les métriques <span class="ref-fiche">→ C06</span> : activation, rétention, conversion ou volume n'ont pas le même sens selon le modèle.</p>`,choice:{kind:"structured",main:"<p>Un modèle économique est une hypothèse de comportement, pas une case à cocher.</p>",alternatives:[{name:"Abonnement",description:"Adapté si la valeur est continue et récurrente. Demande une rétention forte ; mauvais choix si l'usage est rare ou ponctuel."},{name:"Paiement à l'usage",description:"Adapté si la valeur est proportionnelle au volume. Plus juste pour certains clients, mais revenus moins prévisibles."},{name:"Freemium",description:"Adapté si le coût marginal est faible et si la conversion gratuite → payante est structurelle. Dangereux si les gratuits coûtent cher à servir."},{name:"Marketplace / commission",description:"Adapté si le produit facilite une transaction entre deux côtés. Très puissant, mais impose de résoudre le problème d'amorçage des deux faces."}]},senior:"<p>Un product manager expérimenté choisit le modèle selon le moment où l'utilisateur perçoit la valeur. <strong>Faire payer avant la valeur augmente la friction ; faire payer trop tard peut rendre la capture impossible.</strong> Il surveille aussi les incitations : un modèle publicitaire pousse au temps passé, un abonnement pousse à la rétention, une commission pousse au volume de transactions.</p>",errors:"<p><strong>Pattern 1 — Le modèle copié :</strong> on choisit SaaS, freemium ou marketplace parce que les concurrents le font, sans vérifier si les coûts, la fréquence d'usage et le pouvoir d'achat sont similaires.</p><p><strong>Pattern 2 — Le gratuit qui coûte cher :</strong> on lance un plan gratuit pour acquérir vite, mais chaque utilisateur gratuit consomme support, infra ou modération. La croissance accélère la perte.</p><p><strong>Pattern 3 — La valeur et le prix désalignés :</strong> le client paie selon un métrique qui ne correspond pas à la valeur reçue. Le pricing devient une source de friction au lieu d'être une évidence.</p>",invariants:"<p>Un modèle économique durable aligne valeur créée, valeur perçue, valeur capturée et coût de service. S'il manque un de ces éléments, la croissance amplifie le problème au lieu de le résoudre. <strong>Ce qui change :</strong> les formes de pricing, les canaux de paiement et les standards de marché. <strong>Ce qui ne change pas :</strong> un produit viable doit capturer assez de valeur auprès du bon payeur pour financer durablement la valeur qu'il délivre.</p>",practice:{exercices:[{titre:"Tester la cohérence d'un modèle économique",etapes:["Décris qui reçoit la valeur, qui décide, qui paie, et à quel moment chacun intervient.","Choisis deux modèles économiques plausibles et note pour chacun l'hypothèse de comportement nécessaire.","Estime les coûts qui augmentent avec l'usage : support, infrastructure, acquisition, conformité, opérations humaines.","Choisis le modèle le plus cohérent et définis la métrique qui prouverait qu'il fonctionne."],output:"Une comparaison de deux modèles avec payeur, moment de paiement, coûts variables, hypothèse centrale et métrique de validation.",critere:"Le modèle choisi doit expliquer pourquoi le payeur accepte de payer maintenant. Si la réponse est 'parce que le produit est utile', l'analyse est insuffisante."}],piege:"Confondre monétisation et viabilité. Ajouter un prix à un produit ne suffit pas : il faut que le prix corresponde à une valeur perçue et couvre les coûts réels."},verification:["Pourquoi un produit utile peut-il rester non viable économiquement ?","Tu crées un outil utilisé quotidiennement par des employés mais payé par la direction. Quels risques de modèle économique dois-tu analyser ?","Quel invariant relie valeur créée, payeur et coût de service ?"]}},risques:{id:"risques",label:"Risques tech / marché / réglementaires",icon:"⚡",kind:"diagnostic",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:"<p>Les projets échouent rarement à cause d'un seul gros problème visible dès le départ. Ils échouent parce qu'une hypothèse risquée a été laissée dans l'ombre : un canal trop cher, une contrainte réglementaire, une intégration impossible, un cycle de vente trop long. <strong>Nommer les risques tôt transforme l'inquiétude vague en décision gérable.</strong></p>",system:'<p>Les risques synthétisent la faisabilité de la solution <span class="ref-fiche">→ C03</span>, la réalité du marché de cette fiche, et les hypothèses critiques à prioriser <span class="ref-fiche">→ C05</span>. Ils doivent être mesurés ensuite <span class="ref-fiche">→ C06</span> : un risque non relié à un signal reste une peur, pas un objet de pilotage.</p>',choice:{kind:"structured",main:"<p>Les risques ne se traitent pas tous de la même manière. La première décision consiste à les classer correctement.</p>",alternatives:[{name:"Risque marché",description:"Les utilisateurs ne veulent pas, ne changent pas, ne paient pas, ou ne sont pas atteignables. À tester par recherche, landing page, prévente, pilotes."},{name:"Risque technique",description:"L'équipe ne sait pas construire, scaler, intégrer ou maintenir la solution. À tester par spike technique ou prototype ciblé."},{name:"Risque réglementaire / légal",description:"Le produit peut être interdit, coûteux à certifier, ou exposé à des obligations. À traiter tôt avec expertise externe, pas en fin de projet."},{name:"Risque opérationnel",description:"Le service dépend d'humains, de support, de modération, de supply chain. Souvent invisible dans les maquettes, critique en production."}]},senior:"<p>Un product manager expérimenté ne cherche pas à supprimer tous les risques. Il cherche le risque qui peut tuer le projet et le teste avant les autres. <strong>Le risque prioritaire n'est pas le plus anxiogène ; c'est celui qui combine impact élevé, incertitude forte et coût futur croissant.</strong> Il accepte explicitement certains risques faibles pour garder de la vitesse.</p>",errors:"<p><strong>Pattern 1 — Le risque confortable :</strong> l'équipe teste le risque qu'elle sait traiter (souvent technique) et évite le risque marché plus inconfortable. Elle gagne en confiance sur la mauvaise dimension.</p><p><strong>Pattern 2 — Le risque sans propriétaire :</strong> un risque est listé dans un document, mais personne n'est responsable de le réduire ou de le surveiller. Il devient une décoration de gouvernance.</p><p><strong>Pattern 3 — Le risque repoussé au juridique :</strong> on attend la fin pour vérifier conformité, données, contrats ou réglementation. Le risque devient alors une contrainte de refonte.</p>",invariants:"<p>Un risque est une incertitude qui peut changer la décision. S'il ne peut changer aucune action, ce n'est pas un risque prioritaire ; s'il peut tuer le projet, il doit être traité tôt. <strong>Ce qui change :</strong> les types de risques selon les secteurs, technologies et lois. <strong>Ce qui ne change pas :</strong> plus une incertitude critique est découverte tard, plus elle coûte cher à corriger.</p>",practice:{exercices:[{titre:"Construire une matrice de risques utile",etapes:["Liste dix risques possibles pour un projet : marché, technique, réglementaire, opérationnel.","Évalue chaque risque sur impact, probabilité, niveau d'incertitude et coût d'apprentissage tardif.","Choisis les trois risques à traiter en premier et définis pour chacun un test ou une action de réduction.","Nomme un propriétaire et un signal de suivi pour chaque risque prioritaire."],output:"Une matrice de risques avec priorité, action, propriétaire et signal de suivi.",critere:"Chaque risque prioritaire doit pouvoir changer une décision produit. Si aucune décision ne dépend du résultat, il n'est pas prioritaire."}],piege:"Noter beaucoup de risques pour se sentir sérieux, puis continuer comme avant. Une matrice de risques vaut seulement par les décisions qu'elle change."},verification:["Pourquoi tester un risque technique peut-il être une fuite si le vrai risque est marché ?","Tu construis une app santé avec données personnelles. Quels risques doivent être traités avant le MVP public ?","Quel invariant explique pourquoi les risques critiques doivent être abordés tôt ?"]}},quandNePasConstruire:{id:"quandNePasConstruire",label:"Quand ne pas construire",icon:"🛑",kind:"decision",osLabel:"Universel",niveau:"Avancé",sections:{why:"<p>Arrêter un projet tôt ressemble souvent à un échec : il n'y a rien à montrer, aucune release, aucun lancement. Pourtant continuer une opportunité faible consomme l'attention, l'argent et la crédibilité qui auraient pu servir une meilleure direction. <strong>La décision de ne pas construire protège l'équipe contre le coût invisible de l'obstination.</strong></p>",system:`<p>Ce nœud synthétise toute la Partie Conception : problème réel <span class="ref-fiche">→ C01</span>, utilisateurs atteignables <span class="ref-fiche">→ C02</span>, solution testable <span class="ref-fiche">→ C03</span>, marché, modèle économique et risques. Il prépare les décisions de pivot <span class="ref-fiche">→ C05</span> et la boucle d'apprentissage <span class="ref-fiche">→ C06</span> : ne pas construire maintenant est parfois l'apprentissage le plus rentable.</p>`,choice:{kind:"structured",main:"<p>Ne pas construire n'a pas toujours le même sens. Il faut distinguer la nature du refus.</p>",alternatives:[{name:"Arrêter",description:"Les signaux centraux sont négatifs : douleur faible, marché inaccessible, risque disproportionné. Continuer serait de l'obstination."},{name:"Attendre",description:"L'opportunité est plausible mais une condition manque : réglementation, canal, partenaire, maturité technique, budget. On documente ce qui doit changer."},{name:"Réduire",description:"L'idée est trop large mais un noyau viable existe. On coupe le périmètre pour tester l'hypothèse la plus forte."},{name:"Pivoter",description:"Le problème ou segment reste intéressant, mais la solution ou le modèle actuel est invalidé."}]},senior:`<p>Un product manager expérimenté sait que l'attachement émotionnel augmente avec chaque artefact produit : maquette, prototype, pitch, code. <strong>Il fixe donc des critères d'arrêt avant de s'attacher.</strong> Il formule aussi la décision de non-construction comme une allocation de capital : "ce que nous ne construisons pas ici nous permet d'apprendre ou de livrer ailleurs".</p>`,errors:`<p><strong>Pattern 1 — La persévérance théâtrale :</strong> continuer parce qu'abandonner donnerait l'impression d'avoir eu tort. L'équipe protège son image au lieu de protéger ses ressources.</p><p><strong>Pattern 2 — Le pas-maintenant flou :</strong> on dit "plus tard" sans définir quelle condition ferait revenir le sujet. Le projet reste comme bruit permanent dans la roadmap.</p><p><strong>Pattern 3 — Le dernier test infini :</strong> chaque signal négatif déclenche "un test de plus". La validation devient une manière de repousser la décision.</p>`,invariants:"<p>Ne pas construire est une décision active quand elle explicite les critères, les preuves et les conditions de réouverture. Sans cela, ce n'est qu'un report déguisé. <strong>Ce qui change :</strong> les contraintes, le timing, les ressources et les opportunités disponibles. <strong>Ce qui ne change pas :</strong> une équipe crée plus de valeur en abandonnant tôt les options faibles qu'en prouvant tard qu'elle aurait dû s'arrêter.</p>",practice:{exercices:[{titre:"Écrire une décision de non-construction",etapes:["Choisis une idée ou feature attirante mais incertaine.","Liste les signaux pour construire, attendre, réduire, pivoter ou arrêter.","Formule la décision actuelle avec les preuves disponibles et les incertitudes restantes.","Définis la condition concrète qui ferait rouvrir la décision plus tard."],output:"Une note de décision : construire / attendre / réduire / pivoter / arrêter, avec preuves, critères et condition de réouverture.",critere:"La décision doit réduire l'ambiguïté. Si l'équipe peut encore interpréter 'plus tard' comme 'peut-être au prochain sprint', la décision est trop floue."}],piege:"Confondre courage et persévérance. Le courage produit consiste parfois à arrêter une idée séduisante pour préserver l'énergie de l'équipe."},verification:["Pourquoi ne pas construire peut-il être une décision créatrice de valeur plutôt qu'un échec ?","Après 12 entretiens, la douleur existe mais aucun utilisateur ne paierait ni ne changerait d'outil. Quelle décision prends-tu et que documentes-tu ?","Quel invariant distingue un vrai 'pas maintenant' d'un simple report ambigu ?"]}}},maps:{universel:{viewBox:"0 0 820 270",nodes:[{id:"leMarche",x:10,y:100,w:120,h:65},{id:"concurrenceInfo",x:180,y:100,w:175,h:65},{id:"modelesEconomiques",x:410,y:40,w:165,h:65},{id:"risques",x:410,y:165,w:185,h:65},{id:"quandNePasConstruire",x:650,y:100,w:155,h:65}],edges:[{x1:130,y1:132,x2:178,y2:132,label:"conditionne"},{x1:355,y1:115,x2:408,y2:72,label:"révèle"},{x1:355,y1:148,x2:408,y2:185,label:"génère"},{x1:575,y1:73,x2:648,y2:118,label:"informe"},{x1:595,y1:200,x2:648,y2:152,label:"informe"}]}}}),a=e({id:"conception-C05",number:15,title:"Décider et Prioriser",subtitle:"Choisir quoi faire maintenant, quoi tester, quoi reporter et quoi arrêter",badge:"Fiche C05 — Vision Systémique",meta:["5 nœuds · universel"],readingTime:"25 min",description:"Cadres de priorisation pour arbitrer impact, effort, hypothèses critiques, décisions réversibles, coût de l'inaction et pivots.",accent:"decision",nodes:{impactEffort:{id:"impactEffort",label:"Impact vs Effort",icon:"⚖",kind:"modele",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>Quand tout semble important, l'équipe finit souvent par choisir le plus visible, le plus récent, ou le plus facile à défendre en réunion. Le résultat n'est pas une stratégie : c'est une réaction au bruit. <strong>Impact vs Effort rend explicite le compromis entre la valeur attendue et le coût réel de l'obtenir.</strong></p>",system:`<p>Ce nœud transforme les douleurs identifiées <span class="ref-fiche">→ C01</span>, les utilisateurs ciblés <span class="ref-fiche">→ C02</span> et le périmètre de solution <span class="ref-fiche">→ C03</span> en arbitrages comparables. Il nourrit les hypothèses critiques de cette fiche : une option à fort impact mais forte incertitude doit souvent être testée avant d'être construite. Il prépare aussi la mesure <span class="ref-fiche">→ C06</span>, car l'impact annoncé doit devenir observable.</p>`,choice:{kind:"structured",main:"<p>Impact vs Effort est un premier filtre. Il doit être choisi ou complété selon le type de décision.</p>",alternatives:[{name:"Matrice 2x2 Impact / Effort",description:"Bonne pour trier rapidement un backlog flou. Faible précision, mais excellente pour faire apparaître les quick wins et les gouffres à effort."},{name:"RICE",description:"Ajoute Reach et Confidence. Plus robuste quand plusieurs options semblent importantes, parce qu'il force à distinguer impact rêvé et impact confiant."},{name:"WSJF",description:"Intègre coût du délai et durée. Utile quand le timing compte beaucoup, moins adapté aux petites équipes qui manquent de données fiables."}]},senior:"<p>Un product manager expérimenté sait que l'effort n'est pas seulement le temps de développement. <strong>L'effort inclut la maintenance, le support, la migration, la dette créée, et l'énergie d'alignement nécessaire.</strong> Il sait aussi que l'impact doit être relié au problème central : une feature peut être très demandée et pourtant avoir peu d'impact stratégique.</p>",errors:"<p><strong>Pattern 1 — Le quick win addictif :</strong> l'équipe enchaîne les tâches faible effort / impact moyen parce qu'elles donnent une sensation de progrès. Le produit avance, mais les vrais problèmes restent intacts.</p><p><strong>Pattern 2 — L'impact imaginaire :</strong> on attribue un impact élevé à une idée parce qu'elle est séduisante, sans preuve utilisateur ni lien avec une métrique. Le score devient une opinion déguisée.</p><p><strong>Pattern 3 — L'effort sous-estimé :</strong> on compte uniquement la construction initiale et on oublie support, edge cases, documentation, analytics, maintenance. L'option paraît rentable parce que son coût réel est invisible.</p>",invariants:"<p>Prioriser, c'est allouer des ressources limitées à des options imparfaitement connues. Un bon cadre ne supprime pas le jugement ; il rend le jugement visible et discutable. <strong>Ce qui change :</strong> les frameworks, les échelles et les outils de roadmap. <strong>Ce qui ne change pas :</strong> une décision de priorité doit comparer une valeur attendue avec un coût complet, pas une envie avec une estimation optimiste.</p>",practice:{exercices:[{titre:"Prioriser cinq options sans se mentir",etapes:["Liste cinq options concrètes liées au même objectif produit.","Pour chacune, estime impact, effort complet et confiance dans l'impact.","Place-les dans une matrice puis reclasse-les en tenant compte de la confiance.","Identifie l'option que tu ne feras pas maintenant et documente pourquoi."],output:"Une matrice de cinq options avec impact, effort complet, confiance, décision et raison du non-choix.",critere:"Chaque impact doit être relié à un problème, un segment ou une métrique. Si tu ne peux pas dire ce qui changerait concrètement, l'impact est imaginaire."}],piege:"Utiliser la matrice pour confirmer une priorité déjà décidée. Le score doit pouvoir te surprendre, sinon le framework est décoratif."},verification:["Pourquoi l'effort doit-il inclure maintenance et support, pas seulement développement ?","Tu as une option forte demande client / fort effort et une option faible effort / apprentissage rapide. Comment arbitres-tu ?","Quel invariant rend Impact vs Effort utile même si les scores sont approximatifs ?"]}},hypothesesCritiques:{id:"hypothesesCritiques",label:"Hypothèses critiques",icon:"⚠",kind:"validation",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:"<p>Une équipe peut tester beaucoup de choses et rester aveugle au vrai danger. Elle valide une couleur, un wording, une landing page, puis découvre trop tard que les utilisateurs ne changent pas d'habitude ou que personne ne paie. <strong>Une hypothèse critique est une hypothèse qui, si elle est fausse, détruit le projet ou impose un pivot majeur.</strong></p>",system:'<p>Ce nœud prolonge <strong>Hypothèses vs faits</strong> <span class="ref-fiche">→ C02</span> et <strong>La solution comme hypothèse</strong> <span class="ref-fiche">→ C03</span>. Il utilise les risques <span class="ref-fiche">→ C04</span> pour distinguer les hypothèses simplement intéressantes des hypothèses mortelles. Il prépare C06 : une hypothèse critique doit avoir une métrique, un seuil et un délai.</p>',choice:{kind:"structured",main:"<p>Le choix porte sur le type d'hypothèse à tester en premier.</p>",alternatives:[{name:"Hypothèse de douleur",description:"À tester quand le problème lui-même est incertain. Si elle est fausse, inutile de parler solution."},{name:"Hypothèse de changement",description:"À tester quand les utilisateurs reconnaissent le problème mais semblent attachés à leurs habitudes."},{name:"Hypothèse de paiement",description:"À tester tôt quand la viabilité dépend d'un prix, d'un budget ou d'un acheteur différent de l'utilisateur."},{name:"Hypothèse de faisabilité",description:"À tester par spike quand la valeur est claire mais que l'équipe ne sait pas si elle peut livrer sans risque excessif."}]},senior:`<p>Un product manager expérimenté formule la question qui fait peur : "qu'est-ce qui rendrait tout ce plan inutile ?" <strong>Il cherche l'hypothèse dont l'invalidation ferait économiser le plus de temps.</strong> Il sait que tester une hypothèse secondaire donne une sensation de progrès, mais ne réduit pas vraiment le risque du projet.</p>`,errors:"<p><strong>Pattern 1 — Le test confortable :</strong> on teste ce qui est facile à tester, pas ce qui peut tuer le projet. La recherche produit devient une activité rassurante.</p><p><strong>Pattern 2 — La criticité confondue avec l'importance :</strong> une hypothèse peut être importante sans être critique. Si elle est fausse mais corrigeable localement, elle ne doit pas passer avant une hypothèse mortelle.</p><p><strong>Pattern 3 — Le seuil absent :</strong> on lance un test sans décider ce qui invaliderait l'hypothèse. Après coup, tout résultat devient interprétable.</p>",invariants:"<p>Une hypothèse critique mérite d'être testée avant les décisions coûteuses qu'elle conditionne. Sa criticité vient de son pouvoir de changer la direction, pas de son intérêt intellectuel. <strong>Ce qui change :</strong> les méthodes de test et les hypothèses propres au marché. <strong>Ce qui ne change pas :</strong> il faut réduire d'abord l'incertitude qui peut rendre le projet entier incohérent.</p>",practice:{exercices:[{titre:"Identifier les hypothèses qui peuvent tuer le projet",etapes:["Liste dix hypothèses sur ton problème, segment, solution, paiement, acquisition et faisabilité.","Pour chacune, écris ce qui se passerait si elle était fausse.","Classe-les selon le niveau de dommage : local, majeur, fatal.","Choisis les deux hypothèses fatales et définis le test le plus court qui pourrait les invalider."],output:"Une carte d'hypothèses avec conséquence d'invalidation, niveau de dommage et deux tests prioritaires.",critere:"Une hypothèse critique doit changer fortement la décision si elle est fausse. Si le plan reste presque identique, elle n'est pas critique."}],piege:"Appeler critique l'hypothèse qu'on a le plus envie de valider. La criticité se mesure par le coût de l'erreur, pas par l'attachement émotionnel."},verification:["Quelle différence fais-tu entre une hypothèse importante et une hypothèse critique ?","Ton équipe sait que le problème existe, mais ignore si les utilisateurs changeront d'outil. Comment testes-tu cette hypothèse ?","Pourquoi définir un seuil d'invalidation avant le test protège-t-il la décision ?"]}},decisionsReversibles:{id:"decisionsReversibles",label:"Décisions réversibles vs irréversibles",icon:"↔",kind:"modele",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:"<p>Certaines équipes ralentissent tout avec le même niveau de validation : nom de bouton, architecture, pricing, segment cible. D'autres décident vite sur tout et découvrent trop tard qu'elles ont verrouillé une mauvaise direction. <strong>La réversibilité sert à calibrer la quantité de processus au coût réel de l'erreur.</strong></p>",system:`<p>Ce nœud transforme les risques <span class="ref-fiche">→ C04</span> et les choix de périmètre <span class="ref-fiche">→ C03</span> en rythme de décision. Il complète Impact vs Effort : une décision faible effort mais irréversible peut demander plus de rigueur qu'une décision coûteuse mais facilement annulable. Il nourrit les pivots de cette fiche, car pivoter est plus simple quand les décisions précédentes ont gardé des options ouvertes.</p>`,choice:{kind:"structured",main:"<p>Chaque type de décision appelle un niveau de processus différent.</p>",alternatives:[{name:"Décision réversible",description:"Peut être changée vite et à faible coût. Décider rapidement, mesurer, corriger."},{name:"Décision semi-réversible",description:"Peut être changée, mais avec coût de migration ou de communication. Documenter le raisonnement et fixer une date de revue."},{name:"Décision irréversible",description:"Engage architecture, marque, contrats, données ou positionnement. Demande consultation, critères explicites et analyse de risques."}]},senior:"<p>Un product manager expérimenté protège la vitesse en accélérant volontairement les décisions réversibles. <strong>Il ne cherche pas la certitude quand le coût de correction est faible.</strong> À l'inverse, il ralentit sans culpabilité quand une décision crée un verrouillage durable : pricing public, migration de données, promesse commerciale, choix réglementaire.</p>",errors:`<p><strong>Pattern 1 — Le comité pour tout :</strong> chaque décision passe par validation multiple. L'équipe perd sa vitesse sur des choix qui auraient pu être corrigés en une heure.</p><p><strong>Pattern 2 — Le pari irréversible déguisé :</strong> on présente une décision comme "testable" alors qu'elle crée des engagements publics, techniques ou contractuels difficiles à défaire.</p><p><strong>Pattern 3 — L'optionnalité détruite :</strong> une série de petits choix apparemment réversibles ferme progressivement les alternatives. Personne ne voit le verrouillage arriver.</p>`,invariants:"<p>Le bon niveau de rigueur dépend du coût de l'erreur et du coût de retour arrière. Une organisation mature ne décide pas toujours vite ou toujours lentement ; elle calibre. <strong>Ce qui change :</strong> les outils, les circuits de validation et les contraintes d'équipe. <strong>Ce qui ne change pas :</strong> plus une décision est difficile à inverser, plus elle mérite un raisonnement explicite avant engagement.</p>",practice:{exercices:[{titre:"Classer les décisions en cours",etapes:["Liste huit décisions produit ou techniques récentes ou à venir.","Classe chaque décision : réversible, semi-réversible, irréversible.","Pour chaque décision irréversible ou semi-réversible, note ce qui la rend coûteuse à changer.","Définis le niveau de processus adapté : décision immédiate, test limité, RFC, consultation, ou validation formelle."],output:"Un tableau de décisions avec réversibilité, coût de retour arrière et processus adapté.",critere:"Les décisions réversibles doivent avoir un processus léger. Si tout finit en validation lourde, tu n'as pas utilisé la réversibilité pour protéger la vitesse."}],piege:"Classer une décision comme réversible parce qu'elle est techniquement modifiable, en oubliant les coûts humains : formation, confiance client, communication, contrats."},verification:["Pourquoi une décision réversible ne doit-elle pas recevoir le même processus qu'une décision irréversible ?","Changer le pricing public d'un SaaS est-il réversible ? Analyse les coûts visibles et invisibles.","Quel invariant permet de choisir entre décider vite et ralentir pour consulter ?"]}},coutInaction:{id:"coutInaction",label:"Le coût de l'inaction",icon:"⏱",kind:"decision",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:"<p>Reporter une décision paraît prudent parce que rien ne casse immédiatement. Mais pendant l'attente, l'équipe n'apprend pas, les concurrents avancent, les utilisateurs restent bloqués, et l'énergie se dilue. <strong>L'inaction a un coût, même quand elle ne laisse pas de trace dans le backlog.</strong></p>",system:`<p>Ce nœud complète la notion de risque <span class="ref-fiche">→ C04</span> : attendre réduit parfois l'incertitude, mais augmente aussi certains coûts. Il influence la priorisation Impact vs Effort, car une option moyenne aujourd'hui peut devenir critique si le coût du délai augmente. Il prépare la mesure <span class="ref-fiche">→ C06</span> : il faut savoir quel signal justifie d'attendre davantage.</p>`,choice:{kind:"structured",main:"<p>Attendre peut être rationnel ou coûteux. La différence tient à ce qu'on gagne pendant l'attente.</p>",alternatives:[{name:"Attente apprenante",description:"On retarde pour collecter une information précise qui changera la décision. Bonne attente."},{name:"Attente politique",description:"On retarde parce que l'alignement manque. Parfois nécessaire, mais le coût doit être visible."},{name:"Attente anxieuse",description:"On retarde pour éviter le risque émotionnel de trancher. Mauvaise attente : aucune information nouvelle n'est réellement attendue."},{name:"Action limitée",description:"On prend une petite décision réversible pour apprendre au lieu de bloquer sur la décision complète."}]},senior:`<p>Un product manager expérimenté demande : "qu'est-ce que nous saurons dans deux semaines que nous ne savons pas aujourd'hui ?" <strong>Si la réponse est floue, attendre n'est pas une stratégie ; c'est une fuite.</strong> Il rend aussi visible le coût du délai : revenus non capturés, apprentissage repoussé, dette mentale, opportunité concurrente.</p>`,errors:`<p><strong>Pattern 1 — La prudence sans apprentissage :</strong> on attend "d'avoir plus de certitude" sans plan de collecte d'information. Le temps passe, l'incertitude reste.</p><p><strong>Pattern 2 — Le coût invisible :</strong> personne ne chiffre l'impact de l'attente, donc l'inaction semble gratuite face à une action risquée.</p><p><strong>Pattern 3 — Le consensus comme cachette :</strong> on attend que tout le monde soit d'accord, alors que le désaccord reflète un arbitrage réel qui doit être tranché.</p>`,invariants:"<p>Ne pas décider consomme du temps, de l'attention et parfois une fenêtre d'opportunité. L'inaction est justifiée seulement si elle achète une information ou une option qui vaut plus que son coût. <strong>Ce qui change :</strong> les délais, les marchés et les sources d'information. <strong>Ce qui ne change pas :</strong> attendre est une décision qui doit être évaluée comme n'importe quelle autre décision.</p>",practice:{exercices:[{titre:"Calculer le coût d'attendre",etapes:["Choisis une décision actuellement repoussée.","Liste ce que l'attente permettrait d'apprendre ou d'obtenir.","Liste ce que l'attente coûte : utilisateurs, revenus, apprentissage, motivation, risque concurrentiel.","Décide : attendre avec un plan d'information, agir partiellement, ou trancher maintenant."],output:"Une note coût de l'inaction avec information attendue, coûts du délai et décision de prochaine étape.",critere:"Si tu décides d'attendre, tu dois nommer l'information attendue et la date de décision. Sinon, c'est une non-décision."}],piege:"Traiter l'attente comme neutre. Une semaine sans décision est parfois une semaine sans apprentissage, et ce coût doit être assumé."},verification:["Pourquoi l'inaction paraît-elle souvent moins risquée que l'action ?","Une équipe repousse un lancement pour améliorer encore l'onboarding. Comment décides-tu si l'attente vaut son coût ?","Quel invariant transforme l'attente en décision explicite ?"]}},iterationPivots:{id:"iterationPivots",label:"Itération et pivots",icon:"🔄",kind:"decision",osLabel:"Universel",niveau:"Avancé",sections:{why:"<p>Après un résultat décevant, deux erreurs opposées menacent l'équipe : changer trop vite de direction, ou s'acharner sur une direction invalidée. Les deux se ressemblent à l'intérieur : on manque de critères. <strong>Itérer améliore une direction encore plausible ; pivoter change de direction quand une hypothèse critique est infirmée.</strong></p>",system:'<p>Ce nœud relie les hypothèses critiques de cette fiche à la mesure <span class="ref-fiche">→ C06</span>. Il dépend de la solution comme hypothèse <span class="ref-fiche">→ C03</span> : on ne peut pivoter proprement que si on sait quelle hypothèse a échoué. Il boucle aussi vers C01 et C02 : un pivot peut changer le problème, le segment, la solution ou le modèle économique.</p>',choice:{kind:"structured",main:"<p>Un mauvais résultat ne signifie pas toujours la même chose. La décision dépend de ce qui est invalidé.</p>",alternatives:[{name:"Itération d'exécution",description:"Le problème et la solution restent plausibles, mais l'UX, le message ou l'activation sont faibles. On améliore localement."},{name:"Pivot de solution",description:"Le problème et le segment restent vrais, mais la solution ne produit pas la valeur attendue. On change l'approche."},{name:"Pivot de segment",description:"La solution résout une douleur, mais pas pour la cible initiale. On change de segment."},{name:"Pivot de problème",description:"La recherche révèle que le problème central n'est pas celui supposé. On retourne à la découverte."}]},senior:"<p>Un product manager expérimenté fixe les critères de pivot avant les données, quand il est encore capable d'être honnête. <strong>Après le lancement, l'équipe trouvera toujours une bonne raison d'expliquer les mauvais chiffres.</strong> Il distingue aussi un échec de canal, un échec d'activation, un échec de rétention et un échec de valeur : chacun appelle une réponse différente.</p>",errors:"<p><strong>Pattern 1 — Le pivot panique :</strong> un premier signal négatif déclenche un changement de direction avant d'avoir compris ce qui a vraiment échoué. L'équipe apprend moins qu'elle ne bouge.</p><p><strong>Pattern 2 — L'itération d'orgueil :</strong> une hypothèse critique est invalidée, mais l'équipe continue à polir la solution. L'amélioration devient une manière d'éviter le deuil.</p><p><strong>Pattern 3 — Le pivot sans mémoire :</strong> on change de direction sans documenter ce qui a été appris. Les mêmes hypothèses reviennent six mois plus tard sous un autre nom.</p>",invariants:"<p>Itérer et pivoter sont deux réponses différentes à l'apprentissage. L'une conserve la direction et améliore l'exécution ; l'autre change une hypothèse structurante. <strong>Ce qui change :</strong> les métriques, les cycles de test et les formes de pivot. <strong>Ce qui ne change pas :</strong> une équipe doit décider selon l'hypothèse invalidée, pas selon son niveau de fatigue ou d'attachement à la solution.</p>",practice:{exercices:[{titre:"Définir ses critères d'itération et de pivot",etapes:["Choisis une hypothèse de solution et la métrique qui doit la tester.","Définis trois zones de résultat : succès, zone grise, échec clair.","Pour chaque zone, décide à l'avance : persévérer, itérer localement, pivoter, ou arrêter.","Écris ce que tu documenteras après le test pour éviter de réapprendre la même chose."],output:"Une grille résultat → décision avec seuils, action prévue et apprentissage à documenter.",critere:"La zone d'échec doit mener à une vraie décision difficile. Si tout résultat mène à 'on améliore encore', tu n'as pas défini de critère de pivot."}],piege:"Définir les critères après avoir vu les résultats. À ce moment-là, les biais de confirmation et le sunk cost ont déjà pris le volant."},verification:["Quelle différence fais-tu entre itération d'exécution et pivot de solution ?","Une feature a beaucoup d'inscriptions mais très peu de rétention après une semaine. Quelles hypothèses sont possibles et comment décides-tu entre itérer et pivoter ?","Quel invariant explique pourquoi les critères de pivot doivent être fixés avant les données ?"]}}},maps:{universel:{viewBox:"0 0 820 270",nodes:[{id:"impactEffort",x:10,y:100,w:130,h:65},{id:"hypothesesCritiques",x:190,y:100,w:155,h:65},{id:"decisionsReversibles",x:400,y:40,w:180,h:65},{id:"coutInaction",x:400,y:165,w:145,h:65},{id:"iterationPivots",x:640,y:100,w:155,h:65}],edges:[{x1:140,y1:132,x2:188,y2:132,label:"affine"},{x1:345,y1:115,x2:398,y2:72,label:"calibre"},{x1:345,y1:148,x2:398,y2:188,label:"révèle"},{x1:580,y1:73,x2:638,y2:118,label:"conditionne"},{x1:545,y1:198,x2:638,y2:150,label:"déclenche"}]}}}),u=e({id:"conception-C06",number:16,title:"Mesurer et Apprendre",subtitle:"Transformer les métriques en apprentissage et les apprentissages en décisions",badge:"Fiche C06 — Vision Systémique",meta:["5 nœuds · universel"],readingTime:"25 min",description:"Choisir des métriques de substance, distinguer indicateurs précoces et tardifs, formuler des hypothèses testables, éviter les causalités naïves et boucler Build-Measure-Learn.",accent:"validation",nodes:{metriquesVanite:{id:"metriquesVanite",label:"Métriques de vanité vs substance",icon:"📈",kind:"modele",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>Un dashboard peut monter partout et masquer un produit qui ne crée pas de valeur. Plus d'inscriptions, plus de visites, plus de clics : tout semble positif, jusqu'au moment où personne ne revient, ne paie, ou ne change d'habitude. <strong>Les métriques de vanité rassurent ; les métriques de substance changent les décisions.</strong></p>",system:`<p>Ce nœud ferme la boucle commencée avec l'opportunité <span class="ref-fiche">→ C01</span> et la solution comme hypothèse <span class="ref-fiche">→ C03</span>. Une métrique de substance doit mesurer si le problème réel est mieux résolu pour le bon utilisateur <span class="ref-fiche">→ C02</span>. Elle alimente ensuite les décisions d'itération ou de pivot <span class="ref-fiche">→ C05</span>.</p>`,choice:{kind:"structured",main:"<p>Une métrique est utile seulement si elle répond à une question de décision.</p>",alternatives:[{name:"Métrique de vanité",description:"Nombre total d'inscrits, pages vues, téléchargements. Utile pour raconter, insuffisant pour décider."},{name:"Métrique d'activation",description:"Mesure si l'utilisateur atteint le premier moment de valeur. Critique pour savoir si la promesse est comprise."},{name:"Métrique de rétention",description:"Mesure si la valeur est assez forte pour faire revenir. Souvent plus révélatrice que l'acquisition."},{name:"Métrique économique",description:"Conversion, ARPA, marge, CAC payback. Indispensable quand la question est la viabilité."}]},senior:`<p>Un product manager expérimenté demande toujours : "si cette métrique bouge, que faisons-nous différemment ?" <strong>Une métrique sans décision attachée est du décor.</strong> Il préfère une seule métrique douloureuse mais actionnable à dix chiffres flatteurs. Il accepte aussi qu'une bonne métrique rende l'équipe inconfortable : c'est souvent le signe qu'elle mesure la réalité.</p>`,errors:"<p><strong>Pattern 1 — Le compteur flatteur :</strong> on suit un total cumulatif qui monte mécaniquement. Il donne l'impression de progrès même si le produit perd de la valeur.</p><p><strong>Pattern 2 — La métrique sans propriétaire :</strong> tout le monde regarde le chiffre, personne ne sait quelle décision prendre quand il bouge. Le dashboard remplace la responsabilité.</p><p><strong>Pattern 3 — Le changement de thermomètre :</strong> quand une métrique devient inconfortable, on en choisit une autre plus positive. L'équipe optimise son récit, pas le produit.</p>",invariants:"<p>Une métrique de substance relie un comportement observable à la valeur promise. Elle doit pouvoir confirmer, infirmer ou nuancer une hypothèse importante. <strong>Ce qui change :</strong> les outils d'analytics, les dashboards et les standards par industrie. <strong>Ce qui ne change pas :</strong> mesurer n'a de valeur que si cela améliore une décision réelle.</p>",practice:{exercices:[{titre:"Remplacer une métrique de vanité par une métrique de substance",etapes:["Choisis un produit ou une feature et liste cinq métriques faciles à afficher.","Pour chacune, demande : quelle décision changerait si cette métrique montait ou baissait ?","Identifie la métrique qui mesure le mieux la valeur réellement délivrée à l'utilisateur.","Définis le seuil qui déclencherait une action : continuer, itérer, pivoter ou arrêter."],output:"Une métrique de substance choisie, avec hypothèse associée, seuil et décision déclenchée.",critere:"Si la métrique peut monter pendant que les utilisateurs ne reçoivent pas plus de valeur, elle reste une métrique de vanité."}],piege:"Choisir une métrique parce qu'elle est disponible dans l'outil d'analytics. La bonne métrique vient de l'hypothèse, pas du dashboard."},verification:["Pourquoi une métrique qui monte peut-elle quand même être une métrique de vanité ?","Une app a beaucoup d'inscriptions mais très peu de retours en semaine 2. Quelle métrique de substance regarderais-tu et pourquoi ?","Quel invariant permet de décider si une métrique mérite d'être suivie ?"]}},leadingLagging:{id:"leadingLagging",label:"Leading vs Lagging indicators",icon:"⏩",kind:"modele",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:"<p>Certains chiffres arrivent trop tard pour aider. Le churn mensuel te dit que les utilisateurs sont partis ; il ne te dit pas assez tôt lesquels allaient partir. Le revenu trimestriel te dit ce qui a déjà été gagné ou perdu. <strong>Les leading indicators servent à agir avant que les lagging indicators ne confirment le résultat.</strong></p>",system:`<p>Les indicateurs précoces traduisent une hypothèse de causalité issue de la solution <span class="ref-fiche">→ C03</span> : si l'utilisateur accomplit tel comportement tôt, alors la valeur durable devrait suivre. Ils complètent les métriques de substance et alimentent les décisions <span class="ref-fiche">→ C05</span>. Ils doivent être vérifiés contre les résultats tardifs, sinon ils deviennent de nouvelles métriques de vanité.</p>`,choice:{kind:"structured",main:"<p>Le choix dépend du délai entre l'action utilisateur et la valeur finale observée.</p>",alternatives:[{name:"Lagging indicator",description:"Revenu, churn, rétention longue, renouvellement. Fiable mais tardif : bon pour juger, mauvais pour corriger vite."},{name:"Leading indicator",description:"Comportement précoce corrélé à la valeur future : activation, usage d'une feature clé, complétion d'un setup. Bon pour agir vite, à valider."},{name:"Proxy metric",description:"Approximation utilisée quand la valeur finale est difficile à mesurer. Utile seulement si le lien avec la valeur est testé régulièrement."}]},senior:`<p>Un product manager expérimenté ne tombe pas amoureux d'un indicateur précoce. <strong>Il le traite comme une hypothèse : "nous croyons que ce comportement prédit la valeur future".</strong> Il vérifie périodiquement que le signal précoce prédit encore le résultat tardif. Sinon, l'équipe optimise un proxy devenu faux.</p>`,errors:"<p><strong>Pattern 1 — Le proxy sacralisé :</strong> une métrique précoce a été utile au départ, puis devient un objectif permanent même quand elle ne prédit plus la valeur.</p><p><strong>Pattern 2 — Le lagging trop tardif :</strong> l'équipe ne regarde que revenu ou churn, et découvre les problèmes quand ils sont déjà coûteux à corriger.</p><p><strong>Pattern 3 — Le leading non validé :</strong> on suppose qu'un comportement précoce prédit la rétention sans jamais comparer les cohortes. Le signal guide l'équipe sans preuve.</p>",invariants:"<p>Un bon indicateur précoce est une prédiction utile, pas une vérité. Il doit être relié à un résultat final et révalidé quand le produit ou le segment change. <strong>Ce qui change :</strong> les comportements prédictifs selon les produits et marchés. <strong>Ce qui ne change pas :</strong> agir tôt exige un signal précoce dont le lien avec la valeur future est démontré.</p>",practice:{exercices:[{titre:"Définir une paire leading / lagging",etapes:["Choisis une valeur finale importante : rétention, paiement, renouvellement, recommandation.","Identifie trois comportements précoces qui pourraient prédire cette valeur.","Choisis le plus plausible et explique pourquoi il devrait être causal ou prédictif.","Définis comment tu vérifieras dans les données que ce signal prédit réellement le résultat tardif."],output:"Une paire leading/lagging avec hypothèse de lien, méthode de vérification et action si le leading se dégrade.",critere:"Le leading indicator doit être observable avant le lagging et permettre une action concrète. Sinon il ne sert pas à piloter."}],piege:"Choisir comme leading indicator un chiffre simplement disponible tôt. Être précoce ne suffit pas : il doit prédire quelque chose qui compte."},verification:["Pourquoi un lagging indicator fiable peut-il être insuffisant pour piloter un produit ?","Pour un outil de formation en ligne, propose un leading indicator de réussite à 30 jours et explique comment le valider.","Quel invariant empêche de transformer un proxy en objectif aveugle ?"]}},hypothesisDriven:{id:"hypothesisDriven",label:"Hypothesis-driven development",icon:"🔬",kind:"validation",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:"<p>Beaucoup d'équipes livrent des features comme si chaque demande était déjà une réponse. Après le lancement, elles regardent les chiffres et cherchent une histoire. Cette méthode apprend lentement, parce que la question n'était pas posée avant la construction. <strong>Le développement piloté par hypothèses transforme chaque feature en test explicite.</strong></p>",system:`<p>Ce nœud prolonge <strong>La solution comme hypothèse</strong> <span class="ref-fiche">→ C03</span> et les hypothèses critiques <span class="ref-fiche">→ C05</span>. Il utilise les métriques de cette fiche pour trancher, puis renvoie vers l'itération ou le pivot <span class="ref-fiche">→ C05</span>. Il boucle aussi vers C01/C02 quand le test invalide le problème ou le segment, pas seulement l'exécution.</p>`,choice:{kind:"structured",main:"<p>Une hypothèse produit peut être formulée à plusieurs niveaux.</p>",alternatives:[{name:"Hypothèse de problème",description:"Nous croyons que ce segment souffre de cette douleur. À tester avant de parler de solution."},{name:"Hypothèse de solution",description:"Nous croyons que cette approche résout mieux le problème. À tester par MVP, prototype ou expérimentation."},{name:"Hypothèse de croissance",description:"Nous croyons que ce canal ou mécanisme amènera les bons utilisateurs. À tester avec coût et qualité d'acquisition."},{name:"Hypothèse économique",description:"Nous croyons que les utilisateurs ou acheteurs paieront selon ce modèle. À tester par engagement, prévente ou conversion."}]},senior:`<p>Un product manager expérimenté formule l'hypothèse avant d'écrire le ticket. <strong>Le ticket décrit ce qu'on construit ; l'hypothèse décrit pourquoi ça mérite d'être construit et comment on saura si c'était vrai.</strong> Cette discipline change les revues de sprint : la question n'est plus seulement "qu'a-t-on livré ?" mais "qu'a-t-on appris ?"</p>`,errors:`<p><strong>Pattern 1 — La feature sans pari :</strong> le ticket décrit l'interface et les critères d'acceptation, mais pas l'hypothèse de valeur. La livraison ne peut pas apprendre autre chose que "ça marche techniquement".</p><p><strong>Pattern 2 — L'hypothèse infalsifiable :</strong> "les utilisateurs seront plus satisfaits" sans métrique, seuil ni délai. Aucun résultat ne peut vraiment contredire l'équipe.</p><p><strong>Pattern 3 — L'apprentissage non utilisé :</strong> l'expérience invalide l'hypothèse, mais la roadmap continue inchangée. L'équipe mesure sans apprendre.</p>`,invariants:"<p>Une hypothèse utile relie segment, problème, solution, résultat attendu et seuil de décision. Sans seuil, il n'y a pas de test ; sans décision, il n'y a pas d'apprentissage. <strong>Ce qui change :</strong> les formats de tickets, outils d'expérimentation et métriques. <strong>Ce qui ne change pas :</strong> construire sans hypothèse explicite rend l'apprentissage lent, ambigu et vulnérable aux biais.</p>",practice:{exercices:[{titre:"Transformer une feature en hypothèse testable",etapes:["Choisis une feature prévue ou récemment livrée.","Formule : nous croyons que [solution] aidera [segment] à [résultat] parce que [raison].","Définis la métrique, le seuil, le délai et la décision associée à succès / échec.","Réécris le ticket pour inclure l'hypothèse et pas seulement la description fonctionnelle."],output:"Un hypothesis statement complet avec métrique, seuil, délai et décision post-test.",critere:"Quelqu'un doit pouvoir lire l'hypothèse et savoir quel résultat prouverait que la feature ne mérite pas d'être poursuivie."}],piege:"Ajouter une hypothèse vague après coup pour donner une apparence scientifique à une feature déjà décidée."},verification:["Pourquoi une feature sans hypothèse explicite apprend-elle moins qu'une feature formulée comme test ?","Formule une hypothèse testable pour une notification de rappel dans une app de formation.","Quel invariant relie hypothèse, métrique et décision ?"]}},correlationCausalite:{id:"correlationCausalite",label:"Corrélation vs causalité",icon:"⟷",kind:"validation",osLabel:"Universel",niveau:"Avancé",sections:{why:"<p>Après un lancement, deux courbes bougent ensemble : les utilisateurs qui activent une feature restent plus longtemps. L'équipe conclut que la feature cause la rétention, investit dessus, et découvre plus tard que seuls les utilisateurs déjà motivés l'activaient. <strong>Confondre corrélation et causalité mène à optimiser avec confiance la mauvaise chose.</strong></p>",system:`<p>Ce nœud protège toute la boucle de mesure. Il nuance les métriques de substance et les leading indicators : un signal utile peut être prédictif sans être causal. Il conditionne les décisions de pivot <span class="ref-fiche">→ C05</span>, parce qu'une décision lourde exige plus qu'une coïncidence. Il renvoie aussi à la validation sans produit <span class="ref-fiche">→ C02</span> : la qualité du signal dépend de la méthode de test.</p>`,choice:{kind:"structured",main:"<p>Le niveau de preuve nécessaire dépend du coût de la décision.</p>",alternatives:[{name:"Observation corrélationnelle",description:"Rapide, utile pour générer des hypothèses. Ne suffit pas pour prouver un effet."},{name:"Analyse de cohortes",description:"Compare des groupes dans le temps. Plus robuste, mais sensible aux biais de sélection."},{name:"Expérience contrôlée / A-B test",description:"Meilleur outil pour inférer un effet causal si le trafic et la randomisation sont suffisants."},{name:"Test qualitatif causal",description:"Entretiens ou observations pour comprendre le mécanisme. Ne prouve pas l'ampleur, mais révèle pourquoi l'effet pourrait exister."}]},senior:`<p>Un product manager expérimenté ne demande pas seulement "est-ce que les deux métriques bougent ensemble ?" Il demande : <strong>"quelle autre explication pourrait produire le même graphique ?"</strong> Il cherche les variables confondantes : motivation initiale, segment, canal d'acquisition, saisonnalité, maturité utilisateur. Il adapte ensuite le niveau de preuve au risque de la décision.</p>`,errors:"<p><strong>Pattern 1 — Le post hoc magique :</strong> une métrique monte après une release, donc on attribue la hausse à la release. Le calendrier remplace la preuve.</p><p><strong>Pattern 2 — Le biais des utilisateurs motivés :</strong> ceux qui utilisent une feature avancée retiennent mieux, mais parce qu'ils étaient déjà plus engagés. La feature accompagne la valeur, elle ne la cause pas forcément.</p><p><strong>Pattern 3 — La moyenne qui ment :</strong> l'effet positif global cache un effet négatif sur un segment important. L'équipe optimise la moyenne et abîme la cible stratégique.</p>",invariants:"<p>Une corrélation est un signal pour enquêter, pas une preuve pour investir lourdement. Plus la décision est coûteuse ou irréversible, plus le niveau de preuve causale doit être élevé. <strong>Ce qui change :</strong> les méthodes statistiques, les outils d'expérimentation et le volume de données. <strong>Ce qui ne change pas :</strong> deux phénomènes qui bougent ensemble peuvent avoir une cause commune, une causalité inverse ou aucun lien causal direct.</p>",practice:{exercices:[{titre:"Tester une interprétation causale",etapes:["Choisis une corrélation produit plausible : feature utilisée, rétention, conversion, satisfaction.","Écris trois explications alternatives qui pourraient produire cette corrélation.","Définis le test le plus léger pour distinguer l'explication causale des alternatives.","Décide quel niveau de preuve est nécessaire avant d'investir davantage."],output:"Une corrélation analysée avec hypothèse causale, explications alternatives, test proposé et niveau de preuve requis.",critere:"Tu dois avoir au moins une explication alternative crédible. Si tu n'en trouves aucune, tu es probablement trop attaché à ton interprétation."}],piege:"Croire qu'un graphique propre produit une conclusion propre. La causalité vient du design de preuve, pas de la beauté du dashboard."},verification:["Pourquoi les utilisateurs qui activent une feature peuvent-ils mieux retenir sans que la feature cause la rétention ?","Après une refonte, la conversion augmente de 8 %. Quelles explications alternatives dois-tu tester avant de conclure ?","Quel invariant relie coût de décision et niveau de preuve causale nécessaire ?"]}},buildMeasureLearn:{id:"buildMeasureLearn",label:"Build-Measure-Learn",icon:"🔁",kind:"modele",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>Beaucoup d'équipes livrent en continu sans apprendre en continu. Elles construisent, mesurent vaguement, puis construisent encore. Le cycle tourne, mais la connaissance n'augmente pas. <strong>Build-Measure-Learn n'est pas une cadence de livraison ; c'est une boucle de réduction d'incertitude.</strong></p>",system:'<p>Cette boucle clôt la Partie Conception. Elle repart du problème réel <span class="ref-fiche">→ C01</span>, teste les hypothèses utilisateur <span class="ref-fiche">→ C02</span>, construit juste assez de solution <span class="ref-fiche">→ C03</span>, évalue viabilité et risques <span class="ref-fiche">→ C04</span>, puis déclenche décision, itération ou pivot <span class="ref-fiche">→ C05</span>. Sans cette boucle, les fiches précédentes restent des analyses statiques.</p>',choice:{kind:"structured",main:"<p>Le cycle peut commencer à trois endroits selon ce que l'équipe ignore le plus.</p>",alternatives:[{name:"Learn-Build-Measure",description:"Commencer par apprendre quand l'incertitude problème ou segment est forte. Entretiens, observation, tests sans produit."},{name:"Build-Measure-Learn",description:"Construire juste assez quand l'hypothèse est formulée et qu'un comportement réel doit être observé."},{name:"Measure-Learn-Build",description:"Commencer par mesurer quand un produit existe déjà et que les données peuvent révéler le prochain apprentissage."}]},senior:"<p>Un product manager expérimenté cherche à raccourcir la boucle sans appauvrir le signal. <strong>La vitesse n'est pas de livrer plus vite ; c'est d'apprendre plus tôt avec moins de gaspillage.</strong> Il sait aussi qu'une boucle doit produire une décision. Si l'équipe ne change rien après avoir appris, elle n'a pas vraiment appris : elle a seulement collecté de l'information.</p>",errors:"<p><strong>Pattern 1 — Build-Build-Build :</strong> l'équipe appelle ça itération, mais chaque cycle ajoute des features sans question préalable ni décision postérieure.</p><p><strong>Pattern 2 — Measure sans Learn :</strong> les métriques sont regardées en réunion, commentées, puis oubliées. Aucun choix de roadmap ne change.</p><p><strong>Pattern 3 — Learn sans mémoire :</strong> les apprentissages restent dans les têtes ou les Slack. Trois mois plus tard, l'équipe reteste les mêmes hypothèses.</p>",invariants:"<p>Une boucle d'apprentissage vaut par la qualité de la question, la fidélité du signal et la décision qui suit. Construire, mesurer et apprendre sont trois fonctions ; si l'une manque, la boucle est cassée. <strong>Ce qui change :</strong> les outils de build, analytics, expérimentation et documentation. <strong>Ce qui ne change pas :</strong> une équipe progresse durablement quand chaque cycle réduit une incertitude importante et modifie une décision.</p>",practice:{exercices:[{titre:"Planifier une boucle d'apprentissage complète",etapes:["Choisis une incertitude importante issue d'une idée, d'une feature ou d'un risque.","Formule l'hypothèse et le plus petit build nécessaire pour obtenir un signal réel.","Définis la métrique, le seuil, le délai et la décision pour chaque résultat possible.","Prévois où l'apprentissage sera documenté et quelle décision de roadmap il peut changer."],output:"Une boucle Build-Measure-Learn complète : hypothèse, build minimal, mesure, seuils, décisions et trace d'apprentissage.",critere:"La boucle est valide si elle peut changer une décision. Si le résultat ne changerait rien, l'expérience ne mérite pas d'être menée."}],piege:"Confondre boucle d'apprentissage et sprint de livraison. Une livraison sans hypothèse ni décision associée n'est pas une boucle BML."},verification:["Pourquoi Build-Measure-Learn n'est-il pas simplement une façon agile de livrer plus souvent ?","Ton équipe a livré trois itérations et les métriques sont stables. Comment sais-tu si elle apprend vraiment ?","Quel invariant rend une boucle d'apprentissage plus importante qu'une simple cadence de livraison ?"]}}},maps:{universel:{viewBox:"0 0 820 270",nodes:[{id:"metriquesVanite",x:10,y:100,w:175,h:65},{id:"leadingLagging",x:235,y:100,w:155,h:65},{id:"hypothesisDriven",x:445,y:40,w:175,h:65},{id:"correlationCausalite",x:445,y:165,w:175,h:65},{id:"buildMeasureLearn",x:670,y:100,w:140,h:65}],edges:[{x1:185,y1:132,x2:233,y2:132,label:"affine"},{x1:390,y1:115,x2:443,y2:72,label:"structure"},{x1:390,y1:148,x2:443,y2:188,label:"nuance"},{x1:620,y1:73,x2:668,y2:118,label:"alimente"},{x1:620,y1:198,x2:668,y2:152,label:"corrige"}]}}}),p=[i,n,r,o,a,u];export{p as c};
